        function caDateGraphTargetForEntry($serviceType, $label, $source, $typedServiceId)
        {
            $rowSelector = '';
            $fieldSelector = '';
            if ($serviceType === 'CA') {
                $rowSelector = '.ca-service-row[data-id="' . $typedServiceId . '"]';
            } elseif ($serviceType === 'SA-I') {
                $rowSelector = '.sai-service-row[data-id="' . $typedServiceId . '"]';
            } elseif ($serviceType === 'SA-II') {
                $rowSelector = '.saii-service-row[data-id="' . $typedServiceId . '"]';
            } elseif ($serviceType === 'RC') {
                $rowSelector = '.rc-service-row[data-id="' . $typedServiceId . '"]';
            } elseif ($serviceType === 'CR') {
                $rowSelector = '.cr-service-row[data-id="' . $typedServiceId . '"]';
            }

            $actionSelector = '';
            if (strpos($source, 'assessment_planning.') !== false) {
                $rowSelector = '.cr-service-row[data-id="' . $typedServiceId . '"], .rc-service-row[data-id="' . $typedServiceId . '"], .ca-service-row[data-id="' . $typedServiceId . '"]';
                $actionSelector = '.editAssessmentPlanning[data-service="' . $typedServiceId . '"], .addAssessmentPlanning[data-service="' . $typedServiceId . '"]';
                $fieldSelector = ($label === 'QMS Implementation Date') ? '.assessmentImplementationDate' : '.assessmentDate';
            } elseif (strpos($source, 'cdc_report_review.assDate') !== false || strpos($source, 'cdc_report_review.Date') !== false || strpos($source, 'cdc_report_review_office_use') !== false) {
                $actionSelector = '.editCDC[data-service="' . $typedServiceId . '"], .editCDCRC[data-service="' . $typedServiceId . '"], .cdcReport[data-service="' . $typedServiceId . '"]';
                if (strpos($label, 'Assessment') !== false || strpos($label, 'NC(M)') !== false) {
                    $fieldSelector = '.assDate';
                } elseif (strpos($label, 'CDC Date') !== false) {
                    $fieldSelector = '.Date';
                } elseif (strpos($label, 'Rev Date') !== false || strpos($label, 'Issue Date') !== false || strpos($label, 'Certificate Issue Date') !== false) {
                    $fieldSelector = '.revDatecdc';
                }
            } elseif (strpos($source, 'stage_ii_audit_id') !== false) {
                $actionSelector = '.editstageIIAudit2[data-service="' . $typedServiceId . '"], .stageIIAudit[data-service="' . $typedServiceId . '"], .stageIIAuditSai[data-service="' . $typedServiceId . '"]';
                $fieldSelector = (strpos($label, 'Audit Date') !== false) ? '.auditDateIIEdit, .audit_dateII' : '.revDateII2, .review_date';
            } elseif (strpos($source, 'servelance_1_id') !== false) {
                $actionSelector = '.editStage1Servelance[data-service="' . $typedServiceId . '"], .editStage2Servelance[data-service="' . $typedServiceId . '"], .servelancestage2[data-service="' . $typedServiceId . '"]';
            } elseif (strpos($source, 'stage_oneaudit_id') !== false || strpos($source, 'stage_twoaudit_id') !== false) {
                $actionSelector = '.editAuditNotification[data-service="' . $typedServiceId . '"], .editAuditNotificationii[data-service="' . $typedServiceId . '"], .createAuditNotification[data-service1="' . $typedServiceId . '"], .createAuditNotificationii[data-service="' . $typedServiceId . '"]';
            } elseif (strpos($source, 'audit_application.') !== false) {
                $actionSelector = '.editAuditApp[data-caservice-id="' . $typedServiceId . '"], .createAuditApp[data-caservice-id="' . $typedServiceId . '"], .editRCAuditApp[data-service="' . $typedServiceId . '"], .createRCAuditApp[data-service="' . $typedServiceId . '"]';
            } elseif (strpos($source, 'contract_id.') !== false) {
                $actionSelector = '.updateContractReview[data-service="' . $typedServiceId . '"], .createContractReview[data-service="' . $typedServiceId . '"]';
            } elseif (strpos($source, 'certification_aggrement.') !== false) {
                $actionSelector = '.editcertification[data-service="' . $typedServiceId . '"], .certificationBtn[data-service="' . $typedServiceId . '"]';
            } elseif (strpos($source, 'info_update_review.') !== false || strpos($source, 'uploads/reviews') !== false) {
                $actionSelector = '.openInfoUpdationReview[data-service="' . $typedServiceId . '"]';
                $fieldSelector = 'input[name="review_date"]';
            }

            return array('row_selector' => $rowSelector, 'action_selector' => $actionSelector, 'field_selector' => $fieldSelector);
        }

        function caDateGraphAddEntry(array &$entries, $serviceType, $section, $label, $value, $source, $typedServiceId, $universalServiceId)
        {
            $target = caDateGraphTargetForEntry($serviceType, $label, $source, $typedServiceId);
            $entries[] = array(
                'service_type' => $serviceType,
                'section' => $section,
                'label' => $label,
                'value' => caDateGraphHasValue($value) ? trim((string) $value) : '',
                'source' => $source,
                'typed_service_id' => $typedServiceId,
                'universal_service_id' => $universalServiceId,
                'dates' => caDateGraphParseDates($value),
                'status' => 'missing',
                'note' => '',
                'row_selector' => $target['row_selector'],
                'action_selector' => $target['action_selector'],
                'field_selector' => $target['field_selector'],
            );
        }

        function caDateGraphFormatMultiDateValue(array $rows, $dateField, $labelField = '')
        {
            $values = array();
            foreach ($rows as $row) {
                if (!isset($row[$dateField]) || !caDateGraphHasValue($row[$dateField])) {
                    continue;
                }
                $label = ($labelField !== '' && isset($row[$labelField]) && trim((string) $row[$labelField]) !== '') ? trim((string) $row[$labelField]) . ': ' : '';
                $values[] = $label . $row[$dateField];
            }
            return implode('; ', $values);
        }

        function caDateGraphInfoReviewDate($db, $typedServiceId, $customerId)
        {
            $row = caDateGraphFetchOne(
                $db,
                "SELECT review_date, info_form_received_date FROM info_update_review WHERE service_id = :service_id AND customer_id = :customer_id ORDER BY id DESC LIMIT 1",
                array(':service_id' => $typedServiceId, ':customer_id' => $customerId)
            );

            $dateValue = caDateGraphFirstValue($row, array('review_date', 'info_form_received_date'));
            if (caDateGraphHasValue($dateValue)) {
                return $dateValue;
            }

            $jsonFile = __DIR__ . '/uploads/reviews/data_' . $typedServiceId . '_' . $customerId . '.json';
            if (is_file($jsonFile)) {
                $data = json_decode(file_get_contents($jsonFile), true);
                if (is_array($data)) {
                    return caDateGraphFirstValue($data, array('review_date', 'info_form_received_date'));
                }
            }

            return '';
        }

        function caDateGraphCertificateIssueDate($db, array $cdcRow)
        {
            if (empty($cdcRow) || empty($cdcRow['crr_id'])) {
                return '';
            }

            $officeRows = caDateGraphFetchAll(
                $db,
                "SELECT iso_label, rev_date FROM cdc_report_review_office_use WHERE crr_id = :crr_id AND rev_date IS NOT NULL AND rev_date <> '0000-00-00' ORDER BY iso_index ASC",
                array(':crr_id' => $cdcRow['crr_id'])
            );
            $officeDates = caDateGraphFormatMultiDateValue($officeRows, 'rev_date', 'iso_label');
            if (caDateGraphHasValue($officeDates)) {
                return $officeDates;
            }

            return caDateGraphFirstValue($cdcRow, array('revDatecdc', 'Date'));
        }

        function caNormalizeIsoLabelForMatch($label)
        {
            $label = trim((string) $label);
            if ($label === '') {
                return '';
            }

            $label = preg_replace('/iso[\s-]*/i', '', $label);
            $label = preg_replace('/[\s:]/', '', $label);
            return strtolower(trim($label));
        }

        function caFindOfficeUseRowForIso(array $officeRows, $isoLabel, $isoIndex = null)
        {
            if (empty($officeRows)) {
                return array();
            }

            $normalizedTarget = caNormalizeIsoLabelForMatch($isoLabel);

            if ($normalizedTarget !== '') {
                foreach ($officeRows as $row) {
                    $normalizedRow = caNormalizeIsoLabelForMatch(isset($row['iso_label']) ? $row['iso_label'] : '');
                    if ($normalizedRow !== '' && $normalizedRow === $normalizedTarget) {
                        return $row;
                    }
                }

                foreach ($officeRows as $row) {
                    $normalizedRow = caNormalizeIsoLabelForMatch(isset($row['iso_label']) ? $row['iso_label'] : '');
                    if ($normalizedRow !== '' && (strpos($normalizedTarget, $normalizedRow) !== false || strpos($normalizedRow, $normalizedTarget) !== false)) {
                        return $row;
                    }
                }
            }

            if (preg_match('/\d+/', (string) $isoLabel, $targetNumberMatch)) {
                foreach ($officeRows as $row) {
                    if (preg_match('/\d+/', isset($row['iso_label']) ? (string) $row['iso_label'] : '', $rowNumberMatch) && $rowNumberMatch[0] === $targetNumberMatch[0]) {
                        return $row;
                    }
                }
            }

            if ($isoIndex !== null) {
                foreach ($officeRows as $row) {
                    if (isset($row['iso_index']) && (int) $row['iso_index'] === (int) $isoIndex) {
                        return $row;
                    }
                }

                if (isset($officeRows[(int) $isoIndex])) {
                    return $officeRows[(int) $isoIndex];
                }
            }

            return count($officeRows) === 1 ? $officeRows[0] : array();
        }

        function caCertHeaderCertificatesFromLatestCdc(PDO $db, $customerId)
        {
            $statement = $db->prepare(
                "SELECT
                    crr.crr_id,
                    crr.ca_service_id AS serviceca_id,
                    crr.covered_for,
                    crr.cdc_status,
                    crr.Date AS decision_date,
                    crr.revDatecdc AS legacy_issue_date,
                    crr.expiredate AS legacy_expire_date,
                    crr.accreditation AS legacy_accreditation,
                    cou.iso_index,
                    cou.iso_label,
                    cou.certificate_no,
                    cou.rev_date AS issue_date,
                    cou.expire_date,
                    COALESCE(NULLIF(TRIM(cim.accreditation), ''), crr.accreditation) AS accreditation,
                    COALESCE(NULLIF(TRIM(cim.certification_status), ''), crr.cdc_status) AS certification_status
                 FROM cdc_report_review crr
                 INNER JOIN (
                    SELECT MAX(source.crr_id) AS latest_crr_id
                    FROM cdc_report_review source
                    WHERE source.customer_id = :customer_id
                      AND EXISTS (
                        SELECT 1
                        FROM cdc_report_review_office_use source_office
                        WHERE source_office.crr_id = source.crr_id
                      )
                 ) latest ON latest.latest_crr_id = crr.crr_id
                 INNER JOIN cdc_report_review_office_use cou
                    ON cou.crr_id = crr.crr_id
                 LEFT JOIN cdc_iso_metadata cim
                    ON cim.crr_id = crr.crr_id
                   AND cim.iso_index = cou.iso_index
                 ORDER BY cou.iso_index ASC, cou.id ASC"
            );
            $statement->bindValue(':customer_id', (int) $customerId, PDO::PARAM_INT);
            $statement->execute();
            $rows = $statement->fetchAll(PDO::FETCH_ASSOC);

            if (empty($rows)) {
                $latestStatement = $db->prepare(
                    "SELECT crr_id
                     FROM cdc_report_review
                     WHERE customer_id = :customer_id
                     ORDER BY crr_id DESC
                     LIMIT 1"
                );
                $latestStatement->bindValue(':customer_id', (int) $customerId, PDO::PARAM_INT);
                $latestStatement->execute();
                $latestCrrId = (int) $latestStatement->fetchColumn();
                $legacyEntries = aitfBuildLegacyCdcIsoEntries($db, $latestCrrId);
                $legacyCertificates = array();

                foreach ($legacyEntries as $entry) {
                    $legacyCertificates[] = array(
                        'certification_no' => trim((string) ($entry['certificate_no'] ?? '')),
                        'standard_name' => trim((string) ($entry['iso_label'] ?? '')),
                        'issue_date' => $entry['rev_date'] ?? '',
                        'expire_date' => $entry['expire_date'] ?? '',
                        'decision_date' => $entry['decision_date'] ?? '',
                        'cdc_status' => trim((string) ($entry['certification_status'] ?? '')),
                        'serviceca_id' => $entry['serviceca_id'] ?? '',
                        'crr_id' => isset($entry['crr_id']) ? (int) $entry['crr_id'] : 0,
                        'accreditation' => strtoupper(trim((string) ($entry['accreditation'] ?? ''))),
                        'iso_index' => isset($entry['iso_index']) ? (int) $entry['iso_index'] : 0,
                    );
                }

                return $legacyCertificates;
            }

            $certificates = array();
            foreach ($rows as $rowIndex => $row) {
                $isoIndex = isset($row['iso_index']) ? (int) $row['iso_index'] : $rowIndex;
                $coveredStandards = array_values(array_filter(array_map(
                    'trim',
                    explode(',', isset($row['covered_for']) ? (string) $row['covered_for'] : '')
                )));
                $standardName = trim((string) ($row['iso_label'] ?? ''));
                if ($standardName === '' && isset($coveredStandards[$isoIndex])) {
                    $standardName = $coveredStandards[$isoIndex];
                }

                $certificates[] = array(
                    'certification_no' => trim((string) ($row['certificate_no'] ?? '')),
                    'standard_name' => $standardName,
                    'issue_date' => caCertHeaderHasRealDate($row['issue_date'] ?? '')
                        ? $row['issue_date']
                        : ($row['legacy_issue_date'] ?? ''),
                    'expire_date' => caCertHeaderHasRealDate($row['expire_date'] ?? '')
                        ? $row['expire_date']
                        : ($row['legacy_expire_date'] ?? ''),
                    'decision_date' => $row['decision_date'] ?? '',
                    'cdc_status' => trim((string) ($row['certification_status'] ?? ($row['cdc_status'] ?? ''))),
                    'serviceca_id' => $row['serviceca_id'] ?? '',
                    'crr_id' => isset($row['crr_id']) ? (int) $row['crr_id'] : 0,
                    'accreditation' => strtoupper(trim((string) ($row['accreditation'] ?? ($row['legacy_accreditation'] ?? '')))),
                    'iso_index' => $isoIndex,
                );
            }

            return $certificates;
        }

        function caCertHeaderHasRealDate($value)
        {
            $value = trim((string) $value);
            return $value !== '' && $value !== '0000-00-00' && $value !== '0000-00-00 00:00:00' && strtoupper($value) !== 'N/A';
        }

        function caCertHeaderDateAfterMonthsMinusOneDay($baseDate, $months)
        {
            if (!caCertHeaderHasRealDate($baseDate)) {
                return '';
            }

            try {
                $date = new DateTime($baseDate);
                $date->modify('+' . (int) $months . ' months');
                $date->modify('-1 day');
                return $date->format('Y-m-d');
            } catch (Exception $ex) {
                return '';
            }
        }

        function caCertHeaderStandardSchemeKeys($standardName)
        {
            $standard = strtoupper((string) $standardName);

            if (strpos($standard, '14001') !== false) {
                return array('EMS', 'ENVIRONMENTAL');
            }
            if (strpos($standard, '45001') !== false || strpos($standard, '18001') !== false) {
                return array('OHSMS', 'OH&SMS', 'OHS', 'OH&S');
            }
            if (strpos($standard, '9001') !== false) {
                return array('QMS', 'QUALITY');
            }
            if (strpos($standard, '27001') !== false) {
                return array('ISMS', 'INFORMATION');
            }
            if (strpos($standard, '22000') !== false) {
                return array('FSMS', 'FOOD');
            }

            return array();
        }

        function caCertHeaderCertificateFromComment($comment, $standardName, $isoIndex = null)
        {
            $comment = trim((string) $comment);
            if ($comment === '') {
                return '';
            }

            $certBlock = $comment;
            if (preg_match('/certificate\s*no\s*:?\s*(.+)$/is', $comment, $blockMatch)) {
                $certBlock = $blockMatch[1];
            }

            $schemeKeys = caCertHeaderStandardSchemeKeys($standardName);
            foreach ($schemeKeys as $schemeKey) {
                if (preg_match('/\b' . preg_quote($schemeKey, '/') . '\b\s*:?\s*([A-Z0-9\/.-]+)/i', $certBlock, $matches)) {
                    return trim($matches[1], " \t\n\r\0\x0B;,. ");
                }
            }

            if (preg_match_all('/(?:^|[;\n,])\s*([A-Z&]+)\s*:?\s*([A-Z0-9\/.-]+)/i', $certBlock, $pairs, PREG_SET_ORDER)) {
                foreach ($pairs as $pair) {
                    $label = strtoupper(trim($pair[1]));
                    foreach ($schemeKeys as $schemeKey) {
                        if ($label === strtoupper($schemeKey)) {
                            return trim($pair[2], " \t\n\r\0\x0B;,. ");
                        }
                    }
                }
            }

            if ($isoIndex !== null && preg_match_all('/\b[A-Z0-9][A-Z0-9\/.-]*\d[A-Z0-9\/.-]*\b/i', $certBlock, $numbers)) {
                $values = array_values(array_filter(array_map('trim', $numbers[0])));
                return isset($values[(int) $isoIndex]) ? $values[(int) $isoIndex] : '';
            }

            return '';
        }

        function caCertHeaderDashboardDate(array $row, array $keys)
        {
            foreach ($keys as $key) {
                if (isset($row[$key]) && caCertHeaderHasRealDate($row[$key])) {
                    return trim((string) $row[$key]);
                }
            }

            return '';
        }

        function caCertHeaderFindDashboardRow(array $dashboardRows, array $cert, $certIndex, $certificateCount = 0)
        {
            if (empty($dashboardRows)) {
                return array();
            }

            $standardName = isset($cert['standard_name']) ? $cert['standard_name'] : '';
            $standardKey = function_exists('iafDashboardStandardKey') ? iafDashboardStandardKey($standardName) : caNormalizeIsoLabelForMatch($standardName);
            $normalizedStandard = caNormalizeIsoLabelForMatch($standardName);

            foreach ($dashboardRows as $row) {
                $rowStandard = isset($row['standard_name']) ? $row['standard_name'] : '';
                $rowKey = function_exists('iafDashboardStandardKey') ? iafDashboardStandardKey($rowStandard) : caNormalizeIsoLabelForMatch($rowStandard);
                if ($standardKey !== '' && $standardKey !== 'NO_STANDARD' && $rowKey === $standardKey) {
                    return $row;
                }
            }

            foreach ($dashboardRows as $row) {
                $rowNormalized = caNormalizeIsoLabelForMatch(isset($row['standard_name']) ? $row['standard_name'] : '');
                if ($normalizedStandard !== '' && $rowNormalized !== '' && ($normalizedStandard === $rowNormalized || strpos($normalizedStandard, $rowNormalized) !== false || strpos($rowNormalized, $normalizedStandard) !== false)) {
                    return $row;
                }
            }

            if (isset($cert['iso_index'])) {
                foreach ($dashboardRows as $row) {
                    $rowStandard = isset($row['standard_name']) ? trim((string) $row['standard_name']) : '';
                    if ($rowStandard === '' && isset($row['iso_index']) && (int) $row['iso_index'] === (int) $cert['iso_index']) {
                        return $row;
                    }
                }
            }

            if ((int) $certificateCount === count($dashboardRows) && isset($dashboardRows[$certIndex])) {
                return $dashboardRows[$certIndex];
            }

            return (int) $certificateCount === 1 && count($dashboardRows) === 1 ? $dashboardRows[0] : array();
        }

        function caCertHeaderApplyDashboardRows(array $certificates, array $dashboardRows)
        {
            if (empty($dashboardRows)) {
                return $certificates;
            }

            $certificateCount = count($certificates);
            foreach ($certificates as $index => $cert) {
                $dashboardRow = caCertHeaderFindDashboardRow($dashboardRows, $cert, $index, $certificateCount);
                if (empty($dashboardRow)) {
                    continue;
                }

                if (empty($certificates[$index]['standard_name']) && !empty($dashboardRow['standard_name'])) {
                    $certificates[$index]['standard_name'] = $dashboardRow['standard_name'];
                }
                if (!empty($dashboardRow['certificate_number'])) {
                    $certificates[$index]['certification_no'] = trim((string) $dashboardRow['certificate_number']);
                }
                if (!empty($dashboardRow['certification_status'])) {
                    $certificates[$index]['cdc_status'] = trim((string) $dashboardRow['certification_status']);
                }

                $dashboardDecisionDate = caCertHeaderDashboardDate($dashboardRow, array('certificate_issue_date'));
                $dashboardIssueDate = caCertHeaderDashboardDate($dashboardRow, array('issue_date'));
                $dashboardExpireDate = caCertHeaderDashboardDate($dashboardRow, array('expire_date', 'expiry_date'));
                if ($dashboardDecisionDate !== '') {
                    $certificates[$index]['decision_date'] = $dashboardDecisionDate;
                }
                if ($dashboardIssueDate !== '') {
                    $certificates[$index]['issue_date'] = $dashboardIssueDate;
                }
                if ($dashboardExpireDate !== '') {
                    $certificates[$index]['expire_date'] = $dashboardExpireDate;
                }
                $certificates[$index]['dashboard_synced'] = true;
            }

            return $certificates;
        }

        function caCertHeaderCertificatesFromDashboardRows(array $dashboardRows)
        {
            $certificates = array();

            foreach ($dashboardRows as $row) {
                $certificates[] = array(
                    'certification_no' => isset($row['certificate_number']) ? trim((string) $row['certificate_number']) : '',
                    'standard_name' => isset($row['standard_name']) ? trim((string) $row['standard_name']) : '',
                    'issue_date' => caCertHeaderDashboardDate($row, array('issue_date')),
                    'expire_date' => caCertHeaderDashboardDate($row, array('expire_date', 'expiry_date')),
                    'decision_date' => caCertHeaderDashboardDate($row, array('certificate_issue_date')),
                    'cdc_status' => isset($row['certification_status']) ? trim((string) $row['certification_status']) : '',
                    'serviceca_id' => isset($row['svc_id']) ? $row['svc_id'] : '',
                    'iso_index' => isset($row['iso_index']) ? $row['iso_index'] : '',
                    'dashboard_synced' => true,
                );
            }

            return $certificates;
        }



        function caDateGraphAddProposedDates(array &$entries, $db, $serviceType, $section, $typedServiceId, $universalServiceId, array $actions)
        {
            if (empty($universalServiceId)) {
                foreach ($actions as $action => $label) {
                    caDateGraphAddEntry($entries, $serviceType, $section, $label, '', 'ca_service_dates.due_date', $typedServiceId, $universalServiceId);
                }
                return;
            }

            $rows = caDateGraphFetchAll(
                $db,
                "SELECT action, due_date FROM ca_service_dates WHERE service_id = :service_id AND is_deleted = 'N' ORDER BY due_date ASC, action_id ASC",
                array(':service_id' => $universalServiceId)
            );
            $datesByAction = array();
            foreach ($rows as $row) {
                if (isset($row['action']) && !isset($datesByAction[$row['action']])) {
                    $datesByAction[$row['action']] = isset($row['due_date']) ? $row['due_date'] : '';
                }
            }

            foreach ($actions as $action => $label) {
                caDateGraphAddEntry(
                    $entries,
                    $serviceType,
                    $section,
                    $label,
                    isset($datesByAction[$action]) ? $datesByAction[$action] : '',
                    'ca_service_dates.due_date',
                    $typedServiceId,
                    $universalServiceId
                );
            }
        }

        function caDateGraphEntryMinTimestamp(array $entry)
        {
            if (empty($entry['dates'])) {
                return null;
            }

            return min(array_map(function ($date) {
                return $date['timestamp'];
            }, $entry['dates']));
        }

        function caDateGraphEntryMaxTimestamp(array $entry)
        {
            if (empty($entry['dates'])) {
                return null;
            }

            return max(array_map(function ($date) {
                return $date['timestamp'];
            }, $entry['dates']));
        }

        function caDateGraphEntryInternalDatesOk(array $entry)
        {
            if (empty($entry['dates'])) {
                return true;
            }

            $dates = $entry['dates'];
            for ($i = 1; $i < count($dates); $i++) {
                if ($dates[$i]['timestamp'] < $dates[$i - 1]['timestamp']) {
                    return false;
                }
            }

            return true;
        }

        function caDateGraphValidationIssueForEntry(array $entry, array $workflowContext, $lastTimestamp, $lastLabel)
        {
            $label = isset($entry['label']) ? $entry['label'] : '';
            $serviceType = isset($entry['service_type']) ? $entry['service_type'] : '';
            $section = isset($entry['section']) ? $entry['section'] : '';
            $minTimestamp = caDateGraphEntryMinTimestamp($entry);

            if ($label === 'Application Date' && isset($workflowContext['QMS Implementation Date'])) {
                $qmsMaxTimestamp = caDateGraphEntryMaxTimestamp($workflowContext['QMS Implementation Date']);
                if ($qmsMaxTimestamp !== null && $minTimestamp !== null && $minTimestamp <= $qmsMaxTimestamp) {
                    return 'Application Date should be after QMS Implementation Date';
                }
            }

            if ($serviceType === 'CA' && $label === 'Stage-I Audit Date' && isset($workflowContext['QMS Implementation Date'])) {
                $qmsMaxTimestamp = caDateGraphEntryMaxTimestamp($workflowContext['QMS Implementation Date']);
                if ($qmsMaxTimestamp !== null && $minTimestamp !== null) {
                    $minimumStageOneTimestamp = strtotime('+2 months', $qmsMaxTimestamp);
                    if ($minimumStageOneTimestamp !== false && $minTimestamp < $minimumStageOneTimestamp) {
                        return 'Stage-I Audit Date should be at least 2 months after QMS Implementation Date';
                    }
                }
            }

            if ($label === 'Assessment / NC(M) Closing Date') {
                $auditReferenceLabel = ($serviceType === 'CA') ? 'Stage-II Audit Date' : 'Audit Date';
                if (isset($workflowContext[$auditReferenceLabel])) {
                    $auditMaxTimestamp = caDateGraphEntryMaxTimestamp($workflowContext[$auditReferenceLabel]);
                    if ($auditMaxTimestamp !== null && $minTimestamp !== null && $minTimestamp < $auditMaxTimestamp) {
                        return $label . ' should be greater than or equal to ' . $auditReferenceLabel;
                    }
                }
                return '';
            }

            if ($lastTimestamp !== null && $minTimestamp !== null && $minTimestamp < $lastTimestamp) {
                return $section . ' - ' . $label . ' should be greater than ' . $lastLabel;
            }

            return '';
        }

        function caDateGraphBuildForCustomer($db, $customerId)
        {
            $entries = array();
            if (empty($db) || empty($customerId)) {
                return array('entries' => array(), 'summary' => array('ok' => 0, 'issue' => 0, 'missing' => 0, 'total' => 0));
            }

            $services = caDateGraphFetchAll(
                $db,
                "SELECT s.service_id, s.service_type, ca.ca_id, sai.sai_id, saii.saii_id, rc.rc_id
                 FROM service s
                 LEFT JOIN service_type_ca ca ON ca.service = s.service_id
                 LEFT JOIN service_type_sai sai ON sai.service = s.service_id
                 LEFT JOIN service_type_saii saii ON saii.service = s.service_id
                 LEFT JOIN service_type_rc rc ON rc.service = s.service_id
                 WHERE s.customer_id = :customer_id
                 AND s.service_type IN ('CA', 'SA-I', 'SA-II', 'RC')
                 ORDER BY s.service_id ASC",
                array(':customer_id' => $customerId)
            );

            foreach ($services as $service) {
                $serviceEntryStart = count($entries);
                $serviceType = isset($service['service_type']) ? $service['service_type'] : '';
                $universalServiceId = isset($service['service_id']) ? $service['service_id'] : '';
                $typedServiceId = '';

                if ($serviceType === 'CA') {
                    $typedServiceId = isset($service['ca_id']) ? $service['ca_id'] : '';
                } elseif ($serviceType === 'SA-I') {
                    $typedServiceId = isset($service['sai_id']) ? $service['sai_id'] : '';
                } elseif ($serviceType === 'SA-II') {
                    $typedServiceId = isset($service['saii_id']) ? $service['saii_id'] : '';
                } elseif ($serviceType === 'RC') {
                    $typedServiceId = isset($service['rc_id']) ? $service['rc_id'] : '';
                }

                if (empty($typedServiceId)) {
                    continue;
                }

                if ($serviceType === 'CA' || $serviceType === 'RC') {
                    $section = ($serviceType === 'RC') ? 'RC Contract Review' : 'Contract Review';
                    $contractTypedServiceId = $typedServiceId;
                    $contractUniversalServiceId = $universalServiceId;

                    if ($serviceType === 'CA' || $serviceType === 'RC') {
                        $crService = caDateGraphResolveCrServiceForCa($db, $customerId, $universalServiceId);
                        if (!empty($crService['typed_service_id'])) {
                            $contractTypedServiceId = $crService['typed_service_id'];
                            $contractUniversalServiceId = $crService['universal_service_id'];
                        }
                    }

                    $auditApplication = caDateGraphFetchOne(
                        $db,
                        "SELECT application_date, application_rcv_date, review_date FROM audit_application WHERE (service_id = :typed_id OR uni_svc_id = :service_id) ORDER BY audit_id DESC LIMIT 1",
                        array(':typed_id' => $contractTypedServiceId, ':service_id' => $contractUniversalServiceId)
                    );
                    $agreement = caDateGraphFetchOne(
                        $db,
                        "SELECT aggrement_date FROM certification_aggrement WHERE customer_id = :customer_id AND (service = :typed_id OR service = :service_id) ORDER BY id DESC LIMIT 1",
                        array(':customer_id' => $customerId, ':typed_id' => $contractTypedServiceId, ':service_id' => $contractUniversalServiceId)
                    );
                    $assessment = caDateGraphFetchAssessmentPlanning($db, $customerId, array($contractTypedServiceId, $typedServiceId, $contractUniversalServiceId, $universalServiceId));

                    $assessmentTypedServiceId = isset($assessment['service_id']) && caDateGraphHasValue($assessment['service_id']) ? $assessment['service_id'] : $contractTypedServiceId;

                    caDateGraphAddEntry($entries, $serviceType, $section, 'QMS Implementation Date', caDateGraphFirstValue($assessment, array('qms_implementation_date')), 'assessment_planning.qms_implementation_date', $assessmentTypedServiceId, $contractUniversalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Application Date', caDateGraphFirstValue($auditApplication, array('application_date')), 'audit_application.application_date', $contractTypedServiceId, $contractUniversalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Application Received Date', caDateGraphFirstValue($auditApplication, array('application_rcv_date')), 'audit_application.application_rcv_date', $contractTypedServiceId, $contractUniversalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Review Date', caDateGraphFirstValue($auditApplication, array('review_date')), 'audit_application.review_date', $contractTypedServiceId, $contractUniversalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Agreement Date', caDateGraphFirstValue($agreement, array('aggrement_date')), 'certification_aggrement.aggrement_date', $contractTypedServiceId, $contractUniversalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Assessment Planning Date', caDateGraphFirstValue($assessment, array('date')), 'assessment_planning.date', $assessmentTypedServiceId, $contractUniversalServiceId);
                }

                $stageOne = caDateGraphFetchOne(
                    $db,
                    "SELECT intimation_date, audit_dates FROM stage_oneaudit_id WHERE ca_service_id = :typed_id ORDER BY audit_stage_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $stageTwoNotice = caDateGraphFetchOne(
                    $db,
                    "SELECT intimation_date, audit_dates FROM stage_twoaudit_id WHERE service_id = :typed_id ORDER BY audit_stageii_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $stageIReview = caDateGraphFetchOne(
                    $db,
                    "SELECT auditDate, review_date FROM stage_i_audit_id WHERE ca_service_id = :typed_id ORDER BY stage_i_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $stageIIReview = caDateGraphFetchOne(
                    $db,
                    "SELECT audit_dates, review_date FROM stage_ii_audit_id WHERE ca_service_id = :typed_id ORDER BY stage_ii_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $surveillancePlan = caDateGraphFetchOne(
                    $db,
                    "SELECT audit_dates, prepared_date FROM servelance_1_id WHERE service_id = :typed_id ORDER BY servelance_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $rcAuditPlan = caDateGraphFetchOne(
                    $db,
                    "SELECT scheduleii_date, prepared_date FROM audit_scheduleii_id WHERE ca_service = :typed_id ORDER BY audit_scheduleii_id DESC LIMIT 1",
                    array(':typed_id' => $typedServiceId)
                );
                $cdc = caDateGraphFetchCdc($db, $customerId, $typedServiceId);
                $survey = caDateGraphFetchOne(
                    $db,
                    "SELECT survey_date, review_date FROM customer_survey_id WHERE customer_ca = :customer_id AND ca_serviceid = :typed_id ORDER BY survey_id DESC LIMIT 1",
                    array(':customer_id' => $customerId, ':typed_id' => $typedServiceId)
                );

                if ($serviceType === 'CA') {
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-I Intimation Date', caDateGraphFirstValue($stageOne, array('intimation_date')), 'stage_oneaudit_id.intimation_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-I Audit Date', caDateGraphFirstValue($stageIReview, array('auditDate')) ?: caDateGraphFirstValue($stageOne, array('audit_dates')), 'stage_i_audit_id.auditDate / stage_oneaudit_id.audit_dates', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-I Review Date', caDateGraphFirstValue($stageIReview, array('review_date')), 'stage_i_audit_id.review_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-II Intimation Date', caDateGraphFirstValue($stageTwoNotice, array('intimation_date')), 'stage_twoaudit_id.intimation_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-II Audit Date', caDateGraphFirstValue($stageIIReview, array('audit_dates')) ?: caDateGraphFirstValue($stageTwoNotice, array('audit_dates')), 'stage_ii_audit_id.audit_dates / stage_twoaudit_id.audit_dates', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Stage-II Review Date', caDateGraphFirstValue($stageIIReview, array('review_date')), 'stage_ii_audit_id.review_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Assessment / NC(M) Closing Date', caDateGraphFirstValue($cdc, array('assDate', 'Date')), 'cdc_report_review.assDate', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'CDC Date', caDateGraphFirstValue($cdc, array('Date')), 'cdc_report_review.Date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Rev Date / Certificate Issue Date', caDateGraphCertificateIssueDate($db, $cdc), 'cdc_report_review_office_use.rev_date / cdc_report_review.revDatecdc', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'CA', 'CA', 'Feedback Survey Date', caDateGraphFirstValue($survey, array('survey_date', 'review_date')), 'customer_survey_id.survey_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddProposedDates($entries, $db, 'CA', 'After CA - Proposed Dates for SA-I', $typedServiceId, $universalServiceId, array(
                        'Suspension Reminder' => 'Suspension Reminder Proposed Date',
                        'Suspend Letter' => 'Suspend Letter Proposed Date',
                        'Withdrawal Reminder' => 'Withdrawal Reminder Proposed Date',
                        'Withdraw Letter' => 'Withdraw Letter Proposed Date',
                    ));
                } elseif ($serviceType === 'SA-I' || $serviceType === 'SA-II') {
                    $section = $serviceType;
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Information Updation Review Date', caDateGraphInfoReviewDate($db, $typedServiceId, $customerId), 'info_update_review.review_date / uploads/reviews JSON', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Intimation Date', caDateGraphFirstValue($stageOne, array('intimation_date')), 'stage_oneaudit_id.intimation_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Audit Date', caDateGraphFirstValue($stageIIReview, array('audit_dates')) ?: caDateGraphFirstValue($surveillancePlan, array('audit_dates')) ?: caDateGraphFirstValue($stageOne, array('audit_dates')), 'stage_ii_audit_id.audit_dates / servelance_1_id.audit_dates', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Review Date', caDateGraphFirstValue($stageIIReview, array('review_date')), 'stage_ii_audit_id.review_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Assessment / NC(M) Closing Date', caDateGraphFirstValue($cdc, array('assDate', 'Date')), 'cdc_report_review.assDate', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'CDC Date', caDateGraphFirstValue($cdc, array('Date')), 'cdc_report_review.Date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Rev Date / Issue Date', caDateGraphCertificateIssueDate($db, $cdc), 'cdc_report_review_office_use.rev_date / cdc_report_review.revDatecdc', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, $serviceType, $section, 'Feedback Survey Date', caDateGraphFirstValue($survey, array('survey_date', 'review_date')), 'customer_survey_id.survey_date', $typedServiceId, $universalServiceId);

                    if ($serviceType === 'SA-I') {
                        caDateGraphAddProposedDates($entries, $db, 'SA-I', 'After SA-I - Proposed Dates for SA-II', $typedServiceId, $universalServiceId, array(
                            'Suspension Reminder' => 'Suspension Reminder Proposed Date',
                            'Suspend Letter' => 'Suspend Letter Proposed Date',
                            'Withdrawal Reminder' => 'Withdrawal Reminder Proposed Date',
                            'Withdraw Letter' => 'Withdraw Letter Proposed Date',
                        ));
                    } else {
                        caDateGraphAddProposedDates($entries, $db, 'SA-II', 'After SA-II - Proposed Dates for RC', $typedServiceId, $universalServiceId, array(
                            '1st Reminder' => '1st Reminder Proposed Date',
                            '2nd Reminder' => '2nd Reminder Proposed Date',
                            'Expire Letter' => 'Expire Letter Proposed Date',
                        ));
                    }
                } elseif ($serviceType === 'RC') {
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Intimation Date', caDateGraphFirstValue($stageOne, array('intimation_date')) ?: caDateGraphFirstValue($stageTwoNotice, array('intimation_date')), 'stage_oneaudit_id.intimation_date / stage_twoaudit_id.intimation_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Audit Date', caDateGraphFirstValue($stageIIReview, array('audit_dates')) ?: caDateGraphFirstValue($rcAuditPlan, array('scheduleii_date')) ?: caDateGraphFirstValue($stageOne, array('audit_dates')), 'stage_ii_audit_id.audit_dates / audit_scheduleii_id.scheduleii_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Review Date', caDateGraphFirstValue($stageIIReview, array('review_date')) ?: caDateGraphFirstValue($stageIReview, array('review_date')), 'stage_ii_audit_id.review_date / stage_i_audit_id.review_date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Assessment / NC(M) Closing Date', caDateGraphFirstValue($cdc, array('assDate', 'Date')), 'cdc_report_review.assDate', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'CDC Date', caDateGraphFirstValue($cdc, array('Date')), 'cdc_report_review.Date', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Rev Date / Issue Date', caDateGraphCertificateIssueDate($db, $cdc), 'cdc_report_review_office_use.rev_date / cdc_report_review.revDatecdc', $typedServiceId, $universalServiceId);
                    caDateGraphAddEntry($entries, 'RC', 'RC Audit', 'Feedback Survey Date', caDateGraphFirstValue($survey, array('survey_date', 'review_date')), 'customer_survey_id.survey_date', $typedServiceId, $universalServiceId);
                }

                $workflowKey = $serviceType . ':' . $universalServiceId . ':' . $typedServiceId;
                for ($i = $serviceEntryStart; $i < count($entries); $i++) {
                    $entries[$i]['workflow_key'] = $workflowKey;
                }
            }

            $lastTimestamp = null;
            $lastLabel = '';
            $lastWorkflowKey = '';
            $workflowContext = array();
            $summary = array('ok' => 0, 'issue' => 0, 'missing' => 0, 'total' => count($entries));

            foreach ($entries as $index => $entry) {
                $workflowKey = isset($entry['workflow_key']) ? $entry['workflow_key'] : '';
                if ($workflowKey !== $lastWorkflowKey) {
                    $lastTimestamp = null;
                    $lastLabel = '';
                    $workflowContext = array();
                    $lastWorkflowKey = $workflowKey;
                }

                if (empty($entry['dates'])) {
                    $entries[$index]['status'] = 'missing';
                    $entries[$index]['note'] = 'Date not available';
                    $summary['missing']++;
                    continue;
                }

                $internalOk = caDateGraphEntryInternalDatesOk($entry);
                $minTimestamp = caDateGraphEntryMinTimestamp($entry);
                $maxTimestamp = caDateGraphEntryMaxTimestamp($entry);
                $validationIssue = $internalOk ? caDateGraphValidationIssueForEntry($entry, $workflowContext, $lastTimestamp, $lastLabel) : '';

                if (!$internalOk) {
                    $entries[$index]['status'] = 'issue';
                    $entries[$index]['note'] = $entry['label'] . ' dates should be in correct order';
                    $summary['issue']++;
                } elseif ($validationIssue !== '') {
                    $entries[$index]['status'] = 'issue';
                    $entries[$index]['note'] = $validationIssue;
                    $summary['issue']++;
                } else {
                    $entries[$index]['status'] = 'ok';
                    $entries[$index]['note'] = $entry['section'] . ' - ' . $entry['label'] . ' date is correct';
                    $summary['ok']++;
                }

                $workflowContext[$entry['label']] = $entry;

                if ($lastTimestamp === null || $maxTimestamp > $lastTimestamp) {
                    $lastTimestamp = $maxTimestamp;
                    $lastLabel = $entry['section'] . ' - ' . $entry['label'];
                }
            }

            return array('entries' => $entries, 'summary' => $summary);
        }
    }

    // Manage current customer context without exposing customerid in the URL
    // 1) If called via POST (from dashboard or other lists), store the id in session and redirect back to this page
    if (isset($_POST['customerid']) && !empty($_POST['customerid'])) {
        $_SESSION['current_customer_id'] = (int) $_POST['customerid'];
        // header("Location: customerAccount.php");
        // exit;
    }

    // 2) For normal /account requests, hydrate $_GET['customerid'] from session if available
    if ((!isset($_GET['customerid']) || empty($_GET['customerid'])) && isset($_SESSION['current_customer_id']) && !empty($_SESSION['current_customer_id'])) {
        $_GET['customerid'] = (int) $_SESSION['current_customer_id'];
    } else if (isset($_GET['customerid']) && !empty($_GET['customerid'])) {
        // Keep session in sync if an explicit id is ever provided
        $_SESSION['current_customer_id'] = (int) $_GET['customerid'];
    }

    // 3) If we still don't have a customer id, send the user back to the main dashboard
    if (!isset($_GET['customerid']) || empty($_GET['customerid'])) {
        echo "<script>window.location.href='dashboard';</script>";
        exit;
    }

    $dateGraphData = array('entries' => array(), 'summary' => array('ok' => 0, 'issue' => 0, 'missing' => 0, 'total' => 0));
    $customerDocoraAiVisible = aitfCustomerFeatureIsEnabled($db, 'customer_docora_ai_visible');
    $customerDateGraphVisible = aitfCustomerFeatureIsEnabled($db, 'customer_date_graph_visible');
    $customerAiScanSummary = array(
        'document_scan_completed' => false,
        'software_fill_completed' => false,
        'both_completed' => false,
        'last_document_scan_at' => '',
        'last_software_fill_at' => ''
    );

    if (isset($_GET['customerid']) && !empty($_GET['customerid'])) {
        try {
            aitfEnsureSupplierProfileSchema($db);
            aitfAiEnsureSchema($db);
            $clientDetails = "SELECT * FROM customer_info WHERE id = :id";
            $statement = $db->prepare($clientDetails);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $clientInfo = $statement->fetch();
            $isSupplierAccount = aitfCustomerIsSupplier($clientInfo);
            if (!$isSupplierAccount) {
                $customerAiScanSummary = aitfAiFetchCustomerScanCompletion($db, $_GET['customerid']);
            }
            $supplierTypeLabels = array(
                'employee' => 'Employee',
                'contractor' => 'Contractor / Service Provider',
                'goods' => 'Goods Supplier'
            );
            $supplierTypeLabel = ($isSupplierAccount && isset($supplierTypeLabels[$clientInfo['supplier_type']])) ? $supplierTypeLabels[$clientInfo['supplier_type']] : 'Supplier';
            $supplierVerified = ($isSupplierAccount && isset($clientInfo['verification_status']) && $clientInfo['verification_status'] === 'verified');

            // Fetch unique_id (agreement number) from certification_aggrement table
            try {
                $agreementSql = "SELECT aggrement_no FROM certification_aggrement 
                                WHERE customer_id = :customer_id 
                                AND aggrement_no IS NOT NULL 
                                AND aggrement_no != '' 
                                ORDER BY id DESC LIMIT 1";
                $agreementStmt = $db->prepare($agreementSql);
                $agreementStmt->bindParam(':customer_id', $_GET['customerid']);
                $agreementStmt->execute();
                $agreementResult = $agreementStmt->fetch();

                if ($agreementResult && !empty($agreementResult['aggrement_no'])) {
                    $clientInfo['unique_id'] = $agreementResult['aggrement_no'];
                } else {
                    // If no agreement found, leave unique_id as is (may be empty or from customer_info table)
                    if (!isset($clientInfo['unique_id'])) {
                        $clientInfo['unique_id'] = '';
                    }
                }
            } catch (Exception $agreementEx) {
                // Silent fail - keep original unique_id or set empty
                if (!isset($clientInfo['unique_id'])) {
                    $clientInfo['unique_id'] = '';
                }
            }

            $allCertificates = array();
            $customerId = $clientInfo['id'];
            $dashboardCertificateRows = array();

            if (!$isSupplierAccount && function_exists('iafDashboardFetchClientRows')) {
                try {
                    $dashboardCertificateRows = iafDashboardFetchClientRows($db, $customerId);
                } catch (Exception $dashboardRowsEx) {
                    error_log('Customer account dashboard certificate rows failed: ' . $dashboardRowsEx->getMessage());
                    $dashboardCertificateRows = array();
                }
            }

            if (!$isSupplierAccount) {
                // Fetch ALL certificate details for customers with multiple ISO standards
    
                // Get all ISO standards from audit_schedule_id table with their service IDs
                $allStandardsQuery = "SELECT 
                                    asi.schedule_app_standard as standard_name,
                                    asi.serviceca_id,
                                    asi.ref_no,
                                    ci.certification_stage_date as issue_date
                                  FROM audit_schedule_id asi
                                  LEFT JOIN customer_info ci ON asi.customer_ca_id = ci.id
                                  WHERE asi.customer_ca_id = :custId
                                  AND asi.schedule_app_standard IS NOT NULL
                                  AND asi.schedule_app_standard != ''
                                  ORDER BY asi.audit_schedule_id DESC";

                $allStdStmt = $db->prepare($allStandardsQuery);
                $allStdStmt->bindParam(':custId', $customerId);
                $allStdStmt->execute();
                $allStandards = $allStdStmt->fetchAll(PDO::FETCH_ASSOC);

                // Process each standard - SPLIT comma-separated standards
                foreach ($allStandards as $standard) {
                    // Split comma-separated standards (e.g., "ISO 9001:2015,ISO 45001:2018")
                    $standardNames = array_map('trim', explode(',', $standard['standard_name']));

                    foreach ($standardNames as $standardIndex => $singleStandard) {
                        if (empty($singleStandard))
                            continue;

                        $certInfo = array();
                        $certInfo['standard_name'] = $singleStandard;
                        $certInfo['issue_date'] = '';
                        $certInfo['ref_no'] = $standard['ref_no'];
                        $certInfo['serviceca_id'] = $standard['serviceca_id'];
                        $certInfo['iso_index'] = $standardIndex;

                        // Initialize certificate number and ISO-specific fields
                        $certInfo['certification_no'] = '';
                        $certInfo['cdc_status'] = ''; // ISO-specific certification status
                        $certInfo['decision_date'] = ''; // ISO-specific decision date
                        $certInfo['crr_id'] = '';
                        $certInfo['accreditation'] = '';

                        // FIRST: Try to get certificate number and ISO-specific data from CDC tables
                        // This is for multi-ISO clients where each ISO has its own certificate number and status
                        if (!empty($standard['serviceca_id'])) {
                            // Get the crr_id and ISO-specific status/dates for this service
                            $crrQuery = "SELECT crr_id, accreditation, cdc_status, Date as decision_date, revDatecdc as issue_date, expiredate as expire_date, certificateNo, audit_type FROM cdc_report_review WHERE ca_service_id = :svcId ORDER BY Date DESC LIMIT 1";
                            $crrStmt = $db->prepare($crrQuery);
                            $crrStmt->bindParam(':svcId', $standard['serviceca_id']);
                            $crrStmt->execute();
                            $crrData = $crrStmt->fetch(PDO::FETCH_ASSOC);

                            if ($crrData && !empty($crrData['crr_id'])) {
                                $certInfo['crr_id'] = $crrData['crr_id'];
                                $certInfo['accreditation'] = strtoupper(trim((string) ($crrData['accreditation'] ?? '')));

                                // Store ISO-specific status and decision date
                                if (!empty($crrData['cdc_status'])) {
                                    $certInfo['cdc_status'] = $crrData['cdc_status'];
                                }
                                if (!empty($crrData['decision_date'])) {
                                    $certInfo['decision_date'] = $crrData['decision_date'];
                                }

                                // Try to get certificate and dates from office_use using the same ISO matching strategy as the CDC modal.
                                $officeUseQuery = "SELECT iso_index, iso_label, certificate_no, rev_date as issue_date, expire_date
                                              FROM cdc_report_review_office_use 
                                              WHERE crr_id = :crrId 
                                              ORDER BY iso_index ASC";
                                $officeStmt = $db->prepare($officeUseQuery);
                                $officeStmt->bindParam(':crrId', $crrData['crr_id']);
                                $officeStmt->execute();
                                $officeRows = $officeStmt->fetchAll(PDO::FETCH_ASSOC);
                                $officeData = caFindOfficeUseRowForIso($officeRows, $singleStandard, $standardIndex);

                                if (!empty($officeData)) {
                                    if (!empty($officeData['certificate_no']) && trim($officeData['certificate_no']) != '') {
                                        $certInfo['certification_no'] = trim($officeData['certificate_no']);
                                    }
                                    if (!empty($officeData['issue_date'])) {
                                        $certInfo['issue_date'] = $officeData['issue_date'];
                                    }
                                    if (!empty($officeData['expire_date'])) {
                                        $certInfo['expire_date'] = $officeData['expire_date'];
                                    }
                                    error_log("Found office_use row for {$singleStandard}: " . json_encode($officeData));
                                } else {
                                    error_log("No matching office_use row found for {$singleStandard} in crr_id {$crrData['crr_id']}");
                                }
                            }

                            // FALLBACK to old cdc_report_review table only for fields not found in office_use
                            if (empty($certInfo['certification_no']) || empty($certInfo['issue_date']) || empty($certInfo['expire_date'])) {
                                $certQuery = "SELECT revDatecdc as issue_date, expiredate as expire_date, certificateNo
                                          FROM cdc_report_review 
                                          WHERE ca_service_id = :svcId 
                                          ORDER BY Date DESC LIMIT 1";
                                $certStmt = $db->prepare($certQuery);
                                $certStmt->bindParam(':svcId', $standard['serviceca_id']);
                                $certStmt->execute();
                                $certData = $certStmt->fetch(PDO::FETCH_ASSOC);

                                if ($certData) {
                                    if (empty($certInfo['certification_no']) && !empty($certData['certificateNo']) && trim($certData['certificateNo']) != '') {
                                        $certInfo['certification_no'] = trim($certData['certificateNo']);
                                    }
                                    if (empty($certInfo['issue_date']) && !empty($certData['issue_date'])) {
                                        $certInfo['issue_date'] = $certData['issue_date'];
                                    }
                                    if (empty($certInfo['expire_date']) && !empty($certData['expire_date'])) {
                                        $certInfo['expire_date'] = $certData['expire_date'];
                                    }
                                }
                            }
                        }

                        $commentCertNo = caCertHeaderCertificateFromComment(isset($clientInfo['comment']) ? $clientInfo['comment'] : '', $singleStandard, $standardIndex);
                        if ($commentCertNo !== '') {
                            $certInfo['certification_no'] = $commentCertNo;
                        }

                        // FALLBACK: If CDC table is empty, use customer_info.certification_no (for single ISO clients)
                        if (empty($certInfo['certification_no']) && !empty($clientInfo['certification_no'])) {
                            $certInfo['certification_no'] = $clientInfo['certification_no'];
                            error_log("Using fallback cert number from customer_info: " . $clientInfo['certification_no'] . " for " . $singleStandard);
                        } else if (!empty($certInfo['certification_no'])) {
                            error_log("Using CDC cert number: " . $certInfo['certification_no'] . " for " . $singleStandard . " (service_id: " . $standard['serviceca_id'] . ")");
                        } else {
                            error_log("No certificate number found for " . $singleStandard . " (service_id: " . $standard['serviceca_id'] . ")");
                        }

                        if (empty($certInfo['issue_date']) && !empty($standard['issue_date'])) {
                            $certInfo['issue_date'] = $standard['issue_date'];
                        }

                        if (!empty($crrData) && strtoupper(trim(isset($crrData['audit_type']) ? $crrData['audit_type'] : '')) === 'CA') {
                            $certPrintValidUntil = '';
                            try {
                                $certPrintQuery = "SELECT valid_until FROM certificate_print WHERE service_id = :svcId AND valid_until IS NOT NULL AND valid_until <> '' AND valid_until <> '0000-00-00' ORDER BY certificate_id DESC LIMIT 1";
                                $certPrintStmt = $db->prepare($certPrintQuery);
                                $certPrintStmt->bindParam(':svcId', $standard['serviceca_id']);
                                $certPrintStmt->execute();
                                $certPrintRow = $certPrintStmt->fetch(PDO::FETCH_ASSOC);
                                if ($certPrintRow && caCertHeaderHasRealDate(isset($certPrintRow['valid_until']) ? $certPrintRow['valid_until'] : '')) {
                                    $certPrintValidUntil = $certPrintRow['valid_until'];
                                }
                            } catch (Exception $certPrintEx) {
                                $certPrintValidUntil = '';
                            }

                            if ($certPrintValidUntil !== '') {
                                $certInfo['expire_date'] = $certPrintValidUntil;
                            } else {
                                $baseCertificateDate = aitfGetBaseCertificationDate($db, $customerId, isset($crrData['decision_date']) ? $crrData['decision_date'] : '');
                                $dashboardExpireDate = caCertHeaderDateAfterMonthsMinusOneDay($baseCertificateDate, 36);
                                if ($dashboardExpireDate !== '') {
                                    $certInfo['expire_date'] = $dashboardExpireDate;
                                }
                            }
                        }

                        // Calculate expire date if not found (3 years from issue date)
                        if (empty($certInfo['expire_date']) && !empty($certInfo['issue_date'])) {
                            try {
                                $issueDate = new DateTime($certInfo['issue_date']);
                                $issueDate->modify('+3 years');
                                $issueDate->modify('-1 day');
                                $certInfo['expire_date'] = $issueDate->format('Y-m-d');
                            } catch (Exception $e) {
                                $certInfo['expire_date'] = '';
                            }
                        }

                        $allCertificates[] = $certInfo;
                    }
                }

                // The latest CDC office-use rows are the authoritative per-ISO
                // certificate set. Schedule rows remain a fallback for legacy data.
                $latestCdcCertificates = caCertHeaderCertificatesFromLatestCdc($db, $customerId);
                if (!empty($latestCdcCertificates)) {
                    $allCertificates = $latestCdcCertificates;
                }

                if (empty($allCertificates) && !empty($dashboardCertificateRows)) {
                    foreach ($dashboardCertificateRows as $dashboardRow) {
                        $allCertificates[] = array(
                            'certification_no' => isset($dashboardRow['certificate_number']) ? $dashboardRow['certificate_number'] : '',
                            'standard_name' => isset($dashboardRow['standard_name']) ? $dashboardRow['standard_name'] : '',
                            'issue_date' => caCertHeaderDashboardDate($dashboardRow, array('issue_date')),
                            'expire_date' => caCertHeaderDashboardDate($dashboardRow, array('expire_date', 'expiry_date')),
                            'decision_date' => caCertHeaderDashboardDate($dashboardRow, array('certificate_issue_date')),
                            'cdc_status' => isset($dashboardRow['certification_status']) ? $dashboardRow['certification_status'] : '',
                            'serviceca_id' => isset($dashboardRow['svc_id']) ? $dashboardRow['svc_id'] : '',
                            'crr_id' => '',
                            'accreditation' => '',
                            'iso_index' => isset($dashboardRow['iso_index']) ? $dashboardRow['iso_index'] : '',
                            'dashboard_synced' => true,
                        );
                    }
                }

                // Remove duplicates based on standard_name
                $uniqueCertificates = array();
                $seenStandards = array();
                foreach ($allCertificates as $cert) {
                    $key = $cert['standard_name'];
                    if (!isset($seenStandards[$key])) {
                        $uniqueCertificates[] = $cert;
                        $seenStandards[$key] = true;
                    }
                }
                $allCertificates = $uniqueCertificates;

                if (empty($allCertificates) && !empty($dashboardCertificateRows)) {
                    $allCertificates = caCertHeaderCertificatesFromDashboardRows($dashboardCertificateRows);
                } elseif (!empty($dashboardCertificateRows)) {
                    $allCertificates = caCertHeaderApplyDashboardRows($allCertificates, $dashboardCertificateRows);
                }

                // Ensure every ISO header uses the accreditation saved on its latest
                // CDC record, including dashboard fallback certificates.
                $certificateCdcStmt = $db->prepare(
                    "SELECT
                    crr.crr_id,
                    cim.accreditation AS iso_accreditation,
                    cim.certification_status AS iso_certification_status,
                    crr.accreditation AS legacy_accreditation,
                    crr.cdc_status AS legacy_certification_status
                 FROM cdc_report_review crr
                 LEFT JOIN cdc_iso_metadata cim
                   ON cim.crr_id = crr.crr_id
                  AND cim.iso_index = :iso_index
                 WHERE crr.ca_service_id = :service_id
                   AND crr.customer_id = :customer_id
                 ORDER BY crr.crr_id DESC
                 LIMIT 1"
                );
                foreach ($allCertificates as $certificateIndex => $certificateRow) {
                    $serviceCaId = isset($certificateRow['serviceca_id']) ? (int) $certificateRow['serviceca_id'] : 0;
                    if ($serviceCaId <= 0) {
                        continue;
                    }

                    $certificateCdcStmt->bindValue(':service_id', $serviceCaId, PDO::PARAM_INT);
                    $certificateCdcStmt->bindValue(':customer_id', $customerId, PDO::PARAM_INT);
                    $certificateCdcStmt->bindValue(
                        ':iso_index',
                        isset($certificateRow['iso_index']) ? (int) $certificateRow['iso_index'] : $certificateIndex,
                        PDO::PARAM_INT
                    );
                    $certificateCdcStmt->execute();
                    $certificateCdcRow = $certificateCdcStmt->fetch(PDO::FETCH_ASSOC);
                    if (!$certificateCdcRow) {
                        continue;
                    }

                    $allCertificates[$certificateIndex]['crr_id'] = (int) $certificateCdcRow['crr_id'];
                    $isoAccreditation = strtoupper(trim((string) ($certificateCdcRow['iso_accreditation'] ?? '')));
                    if (!in_array($isoAccreditation, array('NABCB', 'SELF'), true)) {
                        $legacyAccreditations = aitfCdcLegacySplitAccreditations(
                            $certificateCdcRow['legacy_accreditation'] ?? ''
                        );
                        $isoIndex = isset($certificateRow['iso_index'])
                            ? (int) $certificateRow['iso_index']
                            : $certificateIndex;
                        $isoAccreditation = $legacyAccreditations[$isoIndex] ?? ($legacyAccreditations[0] ?? '');
                    }
                    if ($isoAccreditation !== '') {
                        $allCertificates[$certificateIndex]['accreditation'] = $isoAccreditation;
                    }

                    if (!empty($certificateCdcRow['iso_certification_status'])) {
                        $allCertificates[$certificateIndex]['cdc_status'] = trim(
                            (string) $certificateCdcRow['iso_certification_status']
                        );
                    }
                }

                // DEBUG: Log certificate data (remove after testing)
                error_log("=== CUSTOMER ACCOUNT DEBUG ===");
                error_log("Customer ID: " . $customerId);
                error_log("Customer Name: " . $clientInfo['customer_name']);
                error_log("Main Cert No from customer_info: " . ($clientInfo['certification_no'] ?? '(NOT SET)'));
                error_log("Total certificates found: " . count($allCertificates));
                foreach ($allCertificates as $idx => $cert) {
                    error_log("Cert " . ($idx + 1) . " - Standard: " . $cert['standard_name'] . ", Cert No: " . ($cert['certification_no'] ?? '(EMPTY)'));
                }

                // If we have certificates from the query, use the first one for backward compatibility
                if (count($allCertificates) > 0) {
                    $clientInfo['standard_name'] = $allCertificates[0]['standard_name'];
                    $clientInfo['issue_date'] = $allCertificates[0]['issue_date'];
                    $clientInfo['expire_date'] = isset($allCertificates[0]['expire_date']) ? $allCertificates[0]['expire_date'] : '';
                }
            }

            $serviceTypes = "SELECT * FROM service_types";
            $statement = $db->prepare($serviceTypes);
            $statement->execute();
            $servicess = $statement->fetchAll();

            $serviceAddTo = "SELECT * FROM service_add_to";
            $statement = $db->prepare($serviceAddTo);
            $statement->execute();
            $addToList = $statement->fetchAll();

            // $caServices = "SELECT cas.ca_id, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, customer_satisy_review , aud.audit_id, service_id, ci.ca_service_id, contractid, soi.audit_stage_id, soi.ca_service_id ,sia.stage_i_id,sia.ca_service_id,sooa.stage_ii_id,sooa.ca_service_id,crr.crr_id,crr.ca_service_id,cfii.control2_id,cfii.caservice_id,asi.audit_schedule_id,serviceca_id FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id sooa on cas.ca_id = sooa.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id   left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id WHERE cas.customer_id = :id";
            // $caServices = "SELECT cas.ca_id,service, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, service_ca_status , aud.audit_id, service_id, ci.ca_service_id, contractid, soi.audit_stage_id, soi.ca_service_id ,sia.stage_i_id,sia.ca_service_id,siia.stage_ii_id,siia.ca_service_id,crr.crr_id,crr.ca_service_id, asi.audit_schedule_id,serviceca_id , asii.audit_scheduleii_id, asii.ca_service, sioi.stage_i_id , sioi.ca_service_id, cfi.control_id, cfi.caservice_id,cusi.survey_id, ca_serviceid, cfii.control2_id,cfii.caservice_id FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id siia on cas.ca_id = siia.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id left join audit_scheduleii_id asii on cas.ca_id = asii.ca_service left join stage_i_audit_id sioi on cas.ca_id = sioi.ca_service_id left join control_formati_id cfi on cas.ca_id = cfi.caservice_id left join customer_survey_id cusi on cas.ca_id = cusi.ca_serviceid left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id WHERE cas.customer_id = :id";
            $caServices = "SELECT cas.ca_id, service, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, service_ca_status, cas.audit_date as caaudit, aud.audit_id, aud.service_id, contractid, soi.audit_stage_id, sia.stage_i_id, siia.stage_ii_id, crr.crr_id, asi.audit_schedule_id, asii.audit_scheduleii_id, sioi.stage_i_id, cfi.control_id, cusi.survey_id, cfii.control2_id, asp.assessment_id, stai.audit_stageii_id, cfp.certificate_id FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id siia on cas.ca_id = siia.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id left join audit_scheduleii_id asii on cas.ca_id = asii.ca_service left join stage_i_audit_id sioi on cas.ca_id = sioi.ca_service_id left join control_formati_id cfi on cas.ca_id = cfi.caservice_id left join customer_survey_id cusi on cas.ca_id = cusi.ca_serviceid left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id left join assessment_planning asp on cas.ca_id = asp.service_id left join stage_twoaudit_id stai on cas.ca_id = stai.service_id left join certificate_print cfp on cas.ca_id = cfp.service_id WHERE cas.customer_id = :id";
            $statement = $db->prepare($caServices);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $allCAservices = $statement->fetchAll();

            //            $caCert = $db->prepare("SELECT cas.ca_id,service, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, service_ca_status , aud.audit_id, aud.service_id, ci.ca_service_id, contractid, soi.audit_stage_id, soi.ca_service_id ,sia.stage_i_id,sia.ca_service_id,siia.stage_ii_id,siia.ca_service_id,crr.crr_id,crr.ca_service_id, asi.audit_schedule_id,serviceca_id , asii.audit_scheduleii_id, asii.ca_service, sioi.stage_i_id , sioi.ca_service_id, cfi.control_id, cfi.caservice_id,cusi.survey_id, ca_serviceid, cfii.control2_id,cfii.caservice_id,asp.assessment_id, asp.service_id,stai.audit_stageii_id, stai.service_id, cfp.certificate_id,cfp.service_id FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id siia on cas.ca_id = siia.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id left join audit_scheduleii_id asii on cas.ca_id = asii.ca_service left join stage_i_audit_id sioi on cas.ca_id = sioi.ca_service_id left join control_formati_id cfi on cas.ca_id = cfi.caservice_id left join customer_survey_id cusi on cas.ca_id = cusi.ca_serviceid left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id left join assessment_planning asp on cas.ca_id = asp.service_id left join stage_twoaudit_id stai on cas.ca_id = stai.service_id left join certificate_print cfp on cas.ca_id = cfp.service_id WHERE cas.customer_id = :id ");
//            $caCert = $db->prepare("SELECT cas.ca_id,service, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, service_ca_status , aud.audit_id, aud.service_id, ci.ca_service_id, contractid, soi.audit_stage_id, soi.ca_service_id ,sia.stage_i_id,sia.ca_service_id,siia.stage_ii_id,siia.ca_service_id,crr.crr_id,crr.ca_service_id, asi.audit_schedule_id,serviceca_id , asii.audit_scheduleii_id, asii.ca_service, sioi.stage_i_id , sioi.ca_service_id, cfi.control_id, cfi.caservice_id,cusi.survey_id, ca_serviceid, cfii.control2_id,cfii.caservice_id,asp.assessment_id, asp.service_id,stai.audit_stageii_id, stai.service_id, cfp.certificate_id,cfp.service_id, ac.id as acid FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id siia on cas.ca_id = siia.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id left join audit_scheduleii_id asii on cas.ca_id = asii.ca_service left join stage_i_audit_id sioi on cas.ca_id = sioi.ca_service_id left join control_formati_id cfi on cas.ca_id = cfi.caservice_id left join customer_survey_id cusi on cas.ca_id = cusi.ca_serviceid left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id left join assessment_planning asp on cas.ca_id = asp.service_id left join stage_twoaudit_id stai on cas.ca_id = stai.service_id left join certificate_print cfp on cas.ca_id = cfp.service_id left join allotment_count as ac on ac.client_id = cas.customer_id WHERE cas.customer_id = :id");
            $caCert = "SELECT ac.id as acid, cas.ca_id,service, application_form, certification_aggrement, signed_notification, signed_copy, audit_report_I, signed_notification_II, audit_report_II, audit_nc_II, customer_satisfaction, service_ca_status , aud.audit_id, aud.service_id, contractid, soi.audit_stage_id, sia.stage_i_id, siia.stage_ii_id, crr.crr_id, asi.audit_schedule_id, asii.audit_scheduleii_id, asii.ca_service, sioi.stage_i_id , cfi.control_id, cfi.caservice_id,cusi.survey_id, ca_serviceid, cfii.control2_id,cfii.caservice_id,asp.assessment_id, asp.service_id,stai.audit_stageii_id, stai.service_id, cfp.certificate_id,cfp.service_id FROM service_type_ca cas left join audit_application aud on cas.ca_id = aud.service_id left join contract_id ci on cas.ca_id = ci.ca_service_id left join stage_oneaudit_id soi on cas.ca_id = soi.ca_service_id left join stage_i_audit_id sia on cas.ca_id = sia.ca_service_id left join stage_ii_audit_id siia on cas.ca_id = siia.ca_service_id left join cdc_report_review crr on cas.ca_id = crr.ca_service_id left join audit_schedule_id asi on cas.ca_id = asi.serviceca_id left join audit_scheduleii_id asii on cas.ca_id = asii.ca_service left join stage_i_audit_id sioi on cas.ca_id = sioi.ca_service_id left join control_formati_id cfi on cas.ca_id = cfi.caservice_id left join customer_survey_id cusi on cas.ca_id = cusi.ca_serviceid left join control_formatii_id cfii on cas.ca_id = cfii.caservice_id left join assessment_planning asp on cas.ca_id = asp.service_id left join stage_twoaudit_id stai on cas.ca_id = stai.service_id left join certificate_print cfp on cas.ca_id = cfp.service_id left join allotment_count as ac on ac.client_id = cas.customer_id WHERE cas.customer_id = :id";
            $statement = $db->prepare($caCert);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $caCertId = $statement->fetch();

            $allRowCount = "SELECT * FROM service where customer_id = :id order by service_id asc";
            $statement = $db->prepare($allRowCount);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $allcaCount = $statement->fetchall();
            // Ensure allcaCount is always an array to prevent foreach errors
            if (!is_array($allcaCount)) {
                $allcaCount = array();
            }
            $totalallCount = count($allcaCount);

            // $caRowCount = "SELECT count(*) as totalcarow FROM service_type_ca WHERE customer_id = :id";
            $caRowCount = "SELECT * FROM service where service_type = 'CA' and customer_id = :id order by service_id desc limit 1";
            $statement = $db->prepare($caRowCount);
            $statement->bindParam(':id', $_GET['customerid']);
            $statement->execute();
            $caCount = $statement->fetch();
