        .go-ai-nav-robot .go-ai-nav-letter {
            font-family: Arial, Helvetica, sans-serif;
            font-size: 8.6px;
            font-weight: 900;
            dominant-baseline: middle;
            text-anchor: middle;
        }

        .go-ai-nav-robot .go-ai-nav-letter-g {
            fill: #67e8f9;
            filter: drop-shadow(0 0 1.6px rgba(34, 211, 238, 0.95));
        }

        .go-ai-nav-robot .go-ai-nav-letter-o {
            fill: #f0abfc;
            filter: drop-shadow(0 0 1.6px rgba(217, 70, 239, 0.9));
        }

        .go-ai-nav-robot .go-ai-nav-smile {
            fill: none;
            stroke: rgba(226, 232, 240, 0.95);
            stroke-width: 0.85;
            stroke-linecap: round;
        }

        .go-ai-tab-word {
            align-items: baseline;
            display: inline-flex;
            gap: 2px;
            white-space: nowrap;
        }

        .go-ai-tab-go {
            background: linear-gradient(90deg, #38bdf8 0%, #a78bfa 52%, #d946ef 100%);
            -webkit-background-clip: text;
            background-clip: text;
            color: transparent;
            font-weight: 900;
        }

        .go-ai-tab-ai {
            color: #f8fafc;
            font-weight: 800;
        }

        .docora-modal-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 32px;
            height: 32px;
            border-radius: 8px;
            background: linear-gradient(135deg, rgba(99, 102, 241, 0.25) 0%, rgba(168, 85, 247, 0.25) 100%);
            border: 1px solid rgba(168, 85, 247, 0.35);
            flex-shrink: 0;
            position: relative;
            overflow: hidden;
            animation: docora-modal-pulse 3s ease-in-out infinite;
        }

        .docora-modal-icon::before {
            content: '';
            position: absolute;
            top: -100%;
            left: -60%;
            width: 40%;
            height: 300%;
            background: linear-gradient(105deg, transparent 0%, rgba(255, 255, 255, 0.25) 50%, transparent 100%);
            animation: docora-shimmer 2.5s ease-in-out infinite;
        }

        .docora-modal-icon svg {
            position: relative;
            z-index: 1;
            overflow: visible;
        }

        @keyframes docora-modal-pulse {

            0%,
            100% {
                box-shadow: 0 0 8px rgba(168, 85, 247, 0.3), 0 0 16px rgba(99, 102, 241, 0.15);
            }

            50% {
                box-shadow: 0 0 14px rgba(168, 85, 247, 0.6), 0 0 28px rgba(99, 102, 241, 0.35);
            }
        }

        @keyframes docora-shimmer {
            0% {
                transform: translateX(-100%) skewX(-15deg);
            }

            100% {
                transform: translateX(400%) skewX(-15deg);
            }
        }

        .docora-welcome-icon {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            width: 28px;
            height: 28px;
            border-radius: 6px;
            background: linear-gradient(135deg, rgba(99, 102, 241, 0.2) 0%, rgba(168, 85, 247, 0.2) 100%);
            border: 1px solid rgba(168, 85, 247, 0.3);
            flex-shrink: 0;
            animation: docora-modal-pulse 3s ease-in-out infinite;
        }

        .docora-welcome-icon svg {
            overflow: visible;
        }

        .go-ai-robot-svg .go-ai-robot-body {
            fill: rgba(15, 23, 42, 0.78);
            stroke: #c084fc;
        }

        .go-ai-robot-svg .go-ai-eye {
            fill: #eef2ff;
            stroke: #a855f7;
        }

        .go-ai-robot-svg .go-ai-eye-text {
            fill: #4c1d95;
            font-family: Arial, Helvetica, sans-serif;
            font-size: 7px;
            font-weight: 800;
            dominant-baseline: middle;
            text-anchor: middle;
        }

        .go-ai-robot-svg .go-ai-antenna,
        .go-ai-robot-svg .go-ai-mouth,
        .go-ai-robot-svg .go-ai-ear {
            fill: none;
            stroke: #c084fc;
            stroke-linecap: round;
            stroke-linejoin: round;
        }

        .go-ai-robot-svg .go-ai-antenna-dot {
            fill: #c084fc;
        }

        @keyframes aitf-pulse-icon {

            0%,
            100% {
                opacity: 0.8;
                transform: scale(1);
            }

            50% {
                opacity: 1;
                transform: scale(1.2);
            }
        }

        .aitf-ai-header-btn {
            align-items: center;
            border-radius: 6px;
            display: inline-flex;
            gap: 6px;
            line-height: 1;
            margin-top: 0 !important;
            padding: 7px 10px !important;
        }

        .aitf-ai-done-badge {
            align-items: center;
            background: rgba(16, 185, 129, 0.18);
            border: 1px solid rgba(187, 247, 208, 0.55);
            border-radius: 999px;
            color: #ecfdf5;
            display: inline-flex;
            font-size: 11px;
            font-weight: 800;
            gap: 5px;
            letter-spacing: 0.02em;
            line-height: 1;
            padding: 6px 9px;
            text-transform: uppercase;
            white-space: nowrap;
        }

        .aitf-ai-done-badge i {
            color: #86efac;
        }

        .aitf-ai-modal {
            z-index: 100000 !important;
        }

        body.aitf-ai-review-active .modal-backdrop {
            z-index: 99999 !important;
        }

        .aitf-ai-modal .modal-dialog {
            width: min(950px, 92vw) !important;
            margin: 30px auto !important;
            z-index: 100001 !important;
        }

        .aitf-ai-modal .modal-content {
            background: #090d16;
            border: 1px solid rgba(99, 102, 241, 0.3);
            border-radius: 16px;
            box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.6), 0 0 40px rgba(99, 102, 241, 0.15);
            overflow: hidden;
            color: #f1f5f9;
            font-family: 'Outfit', 'Inter', system-ui, -apple-system, sans-serif;
        }

        .aitf-ai-modal .modal-header {
            background: #070a10;
            border-bottom: 1px solid rgba(99, 102, 241, 0.15);
            padding: 18px 24px;
            display: flex;
            align-items: center;
            justify-content: space-between;
        }

        .aitf-ai-modal .modal-header .close {
            color: #94a3b8;
            opacity: 1;
            font-size: 26px;
            font-weight: 300;
            text-shadow: none;
            transition: color 0.2s, transform 0.2s;
            margin-top: 0;
            padding: 10px;
        }

        .aitf-ai-modal .modal-header .close:hover {
            color: #fff;
            transform: scale(1.1);
        }

        .aitf-ai-modal .modal-title {
            font-size: 20px;
            font-weight: 700;
            color: #f1f5f9;
            display: flex;
            align-items: center;
            gap: 10px;
            margin: 0;
        }

        .aitf-ai-modal .modal-body {
            padding: 24px;
            background: #090d16;
        }

        .aitf-ai-welcome {
            background: linear-gradient(135deg, rgba(30, 41, 59, 0.45) 0%, rgba(15, 23, 42, 0.65) 100%);
            border: 1px solid rgba(99, 102, 241, 0.15);
            border-radius: 12px;
            margin-bottom: 20px;
            padding: 16px 20px;
            position: relative;
            overflow: hidden;
        }

        .aitf-ai-welcome::before {
            content: '';
            position: absolute;
            top: 0;
            left: 0;
            width: 4px;
            height: 100%;
            background: linear-gradient(to bottom, #6366f1, #d946ef);
        }

        .aitf-ai-welcome-title {
            color: #e2e8f0;
            font-size: 16px;
            font-weight: 700;
            margin-bottom: 6px;
            display: flex;
            align-items: center;
            gap: 8px;
        }

        .aitf-ai-prompt-box {
            background: #111827;
            border: 1px solid rgba(168, 85, 247, 0.2);
            border-radius: 14px;
            padding: 18px;
            margin-bottom: 20px;
            box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3), 0 4px 20px rgba(0, 0, 0, 0.15);
            transition: border-color 0.3s, box-shadow 0.3s;
        }

        .aitf-ai-prompt-box:focus-within {
            border-color: rgba(168, 85, 247, 0.5);
            box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3), 0 0 15px rgba(168, 85, 247, 0.2);
        }

        .aitf-ai-prompt-box label {
            display: flex;
            align-items: center;
            gap: 6px;
            color: #a5b4fc;
            font-size: 12px;
            font-weight: 700;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            margin-bottom: 12px;
            padding-left: 4px;
        }

        .aitf-ai-prompt-box textarea {
            background: transparent !important;
            border: none !important;
            color: #f1f5f9 !important;
            font-size: 16px !important;
            line-height: 1.6;
            min-height: 80px;
            resize: vertical;
            width: 100%;
            padding: 4px 50px 4px 6px;
            box-shadow: none !important;
            outline: none !important;
        }

        .aitf-ai-prompt-box textarea::placeholder {
            color: #4b5563;
        }

        .aitf-ai-input-wrapper {
            position: relative;
            width: 100%;
        }

        .btn-ai-send {
            position: absolute;
            right: 8px;
            bottom: 8px;
            width: 38px;
            height: 38px;
            border-radius: 50%;
            background: linear-gradient(135deg, #a855f7 0%, #7c3aed 100%);
            border: none;
            color: #fff;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 4px 10px rgba(168, 85, 247, 0.4);
            z-index: 10;
        }

        .btn-ai-send:hover {
            transform: scale(1.08);
            box-shadow: 0 0 14px rgba(168, 85, 247, 0.6);
            background: linear-gradient(135deg, #b86bf8 0%, #8b4ef0 100%);
        }

        .btn-ai-send:active {
            transform: scale(0.95);
        }

        .btn-ai-send:disabled {
            background: #1e293b;
            color: #475569;
            box-shadow: none;
            cursor: not-allowed;
            transform: none;
        }

        .aitf-ai-model-strip {
            align-items: center;
            display: flex;
            flex-wrap: wrap;
            gap: 12px;
            margin-top: 14px;
            padding-top: 14px;
            border-top: 1px solid rgba(255, 255, 255, 0.08);
        }

        .aitf-ai-model-label {
            color: #94a3b8;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.08em;
            text-transform: uppercase;
        }

        .aitf-ai-model-options {
            display: flex;
            gap: 10px;
        }

        .aitf-ai-model-option {
            background: #0d1321;
            border: 1px solid rgba(148, 163, 184, 0.15);
            border-radius: 10px;
            color: #cbd5e1;
            cursor: pointer;
            padding: 8px 16px;
            text-align: left;
            transition: all 0.2s ease;
            display: flex;
            flex-direction: column;
            gap: 2px;
            min-width: 160px;
        }

        .aitf-ai-model-option:hover {
            border-color: rgba(168, 85, 247, 0.4);
            background: rgba(255, 255, 255, 0.02);
        }

        .aitf-ai-model-option.active {
            background: rgba(168, 85, 247, 0.1);
            border-color: #a855f7;
            box-shadow: 0 0 10px rgba(168, 85, 247, 0.4);
            color: #f8fafc;
        }

        .aitf-ai-model-topline {
            align-items: center;
            display: flex;
            justify-content: space-between;
            gap: 8px;
            width: 100%;
        }

        .aitf-ai-model-name {
            font-size: 13px;
            font-weight: 700;
        }

        .aitf-ai-model-badge {
            border-radius: 4px;
            background: rgba(168, 85, 247, 0.15);
            border: 1px solid rgba(168, 85, 247, 0.3);
            color: #d8b4fe;
            font-size: 9px;
            font-weight: 800;
            padding: 1px 4px;
        }

        .aitf-ai-model-desc {
            color: #64748b;
            font-size: 11px;
            font-weight: 500;
        }

        .aitf-ai-metrics {
            color: #94a3b8;
            font-size: 13px;
        }

        /* Sleek Button Styles */
        .btn-ai-primary {
            background: linear-gradient(135deg, #4f46e5 0%, #7c3aed 50%, #c084fc 100%);
            background-size: 200% auto;
            border: none;
            color: #ffffff !important;
            font-weight: 600;
            padding: 8px 18px;
            border-radius: 8px;
            transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
            box-shadow: 0 4px 12px rgba(79, 70, 229, 0.3);
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-ai-primary:hover {
            background-position: right center;
            transform: translateY(-1px);
            box-shadow: 0 6px 20px rgba(124, 58, 237, 0.45);
        }

        .btn-ai-primary:active {
            transform: translateY(1px);
        }

        .btn-ai-primary:disabled {
            background: #1e293b !important;
            color: #475569 !important;
            box-shadow: none;
            cursor: not-allowed;
            transform: none;
        }

        .btn-ai-secondary {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            color: #e2e8f0 !important;
            font-weight: 500;
            padding: 8px 16px;
            border-radius: 8px;
            transition: all 0.2s;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .btn-ai-secondary:hover {
            background: rgba(255, 255, 255, 0.1);
            border-color: rgba(255, 255, 255, 0.2);
            color: #ffffff !important;
        }

        .btn-ai-secondary:disabled {
            opacity: 0.5;
            cursor: not-allowed;
        }

        /* Documents Section Styles */
        .aitf-ai-documents-section {
            margin-top: 25px;
            margin-bottom: 25px;
        }

        .aitf-ai-documents-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 12px;
            flex-wrap: wrap;
            gap: 12px;
        }

        .aitf-ai-documents-header .aitf-ai-section-title {
            font-size: 16px;
            font-weight: 700;
            color: #cbd5e1;
            display: flex;
            align-items: center;
            gap: 8px;
            margin: 0;
        }

        .aitf-ai-doc-actions {
            display: flex;
            flex-wrap: wrap;
            gap: 8px;
        }

        /* AI Thinking Terminal Console Log */
        .aitf-ai-work-steps {
            background: linear-gradient(145deg, rgba(5, 7, 12, 0.96), rgba(12, 18, 31, 0.94));
            border: 1px solid rgba(99, 102, 241, 0.25);
            border-radius: 12px;
            padding: 20px;
            margin: 16px 0;
            display: none;
            box-shadow: 0 18px 45px rgba(0, 0, 0, 0.48), inset 0 1px 0 rgba(255, 255, 255, 0.04);
            position: relative;
            overflow: hidden;
        }

        .aitf-ai-work-steps::before {
            content: '';
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 12% 18%, rgba(99, 102, 241, 0.14), transparent 30%),
                radial-gradient(circle at 84% 8%, rgba(168, 85, 247, 0.10), transparent 28%);
            pointer-events: none;
        }

        .aitf-ai-work-title {
            color: #e2e8f0;
            font-weight: 700;
            font-size: 15px;
            margin-bottom: 16px;
            display: flex;
            align-items: center;
            gap: 10px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-work-title-pulse {
            align-items: center;
            background: rgba(99, 102, 241, 0.14);
            border: 1px solid rgba(165, 180, 252, 0.25);
            border-radius: 50%;
            box-shadow: 0 0 18px rgba(99, 102, 241, 0.22);
            display: inline-flex;
            height: 30px;
            justify-content: center;
            width: 30px;
            animation: aitf-soft-pulse 2.2s ease-in-out infinite;
        }

        .aitf-ai-work-title-pulse i {
            color: #a5b4fc;
        }

        .aitf-ai-work-live {
            background: rgba(16, 185, 129, 0.10);
            border: 1px solid rgba(52, 211, 153, 0.26);
            border-radius: 999px;
            color: #86efac;
            font-size: 10px;
            font-weight: 800;
            letter-spacing: 0.08em;
            margin-left: auto;
            padding: 4px 8px;
        }

        .aitf-ai-work-content {
            display: flex;
            align-items: center;
            gap: 24px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-orb-container {
            flex-shrink: 0;
            width: 104px;
            height: 104px;
            position: relative;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .aitf-ai-orb {
            align-items: center;
            width: 58px;
            height: 58px;
            border-radius: 50%;
            background:
                radial-gradient(circle at 32% 26%, rgba(248, 250, 252, 0.92) 0%, rgba(165, 180, 252, 0.92) 14%, transparent 28%),
                radial-gradient(circle at 50% 58%, #818cf8 0%, #6366f1 46%, #4338ca 100%);
            box-shadow: 0 0 22px rgba(99, 102, 241, 0.62), 0 0 42px rgba(139, 92, 246, 0.34);
            animation: pulse-orb 2.8s infinite ease-in-out;
            color: #eff6ff;
            display: flex;
            font-size: 14px;
            font-weight: 900;
            justify-content: center;
            letter-spacing: 0.04em;
            position: relative;
            z-index: 2;
        }

        .aitf-ai-orb-ring {
            position: absolute;
            border: 1px solid rgba(165, 180, 252, 0.34);
            border-radius: 50%;
            z-index: 1;
        }

        .aitf-ai-orb-ring.ring-one {
            width: 88px;
            height: 88px;
            border-style: dashed;
            animation: rotate-ring 9s linear infinite;
        }

        .aitf-ai-orb-ring.ring-two {
            width: 102px;
            height: 72px;
            border-color: rgba(168, 85, 247, 0.28);
            transform: rotate(-24deg);
            animation: rotate-ring-tilt 12s linear infinite;
        }

        .aitf-ai-particle {
            background: #a5b4fc;
            border-radius: 50%;
            box-shadow: 0 0 10px rgba(165, 180, 252, 0.8);
            height: 4px;
            position: absolute;
            width: 4px;
            z-index: 3;
        }

        .particle-one {
            animation: aitf-particle-one 4s ease-in-out infinite;
            left: 16px;
            top: 25px;
        }

        .particle-two {
            animation: aitf-particle-two 5s ease-in-out infinite;
            right: 18px;
            top: 34px;
        }

        .particle-three {
            animation: aitf-particle-three 4.6s ease-in-out infinite;
            bottom: 24px;
            right: 34px;
        }

        @keyframes pulse-orb {

            0%,
            100% {
                transform: scale(0.95);
                filter: brightness(1) drop-shadow(0 0 10px rgba(99, 102, 241, 0.5));
            }

            50% {
                transform: scale(1.08);
                filter: brightness(1.25) drop-shadow(0 0 25px rgba(139, 92, 246, 0.8));
            }
        }

        @keyframes rotate-ring {
            100% {
                transform: rotate(360deg);
            }
        }

        @keyframes rotate-ring-tilt {
            100% {
                transform: rotate(336deg);
            }
        }

        @keyframes aitf-soft-pulse {

            0%,
            100% {
                box-shadow: 0 0 10px rgba(99, 102, 241, 0.18);
            }

            50% {
                box-shadow: 0 0 22px rgba(99, 102, 241, 0.42);
            }
        }

        @keyframes aitf-particle-one {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.45;
            }

            50% {
                transform: translate(14px, 20px);
                opacity: 1;
            }
        }

        @keyframes aitf-particle-two {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.35;
            }

            50% {
                transform: translate(-18px, 18px);
                opacity: 0.95;
            }
        }

        @keyframes aitf-particle-three {

            0%,
            100% {
                transform: translate(0, 0);
                opacity: 0.4;
            }

            50% {
                transform: translate(-10px, -18px);
                opacity: 0.9;
            }
        }

        .aitf-ai-work-log {
            flex-grow: 1;
            font-family: 'SFMono-Regular', Consolas, 'Courier New', monospace;
            background: rgba(2, 6, 23, 0.68);
            border: 1px solid rgba(148, 163, 184, 0.12);
            border-radius: 8px;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
            color: #cbd5e1;
            font-size: 12px;
            height: 126px;
            line-height: 1.55;
            overflow-y: auto;
            padding: 12px 14px;
        }

        .aitf-ai-log-line {
            align-items: baseline;
            display: flex;
            gap: 8px;
            margin: 2px 0;
            min-height: 19px;
            opacity: 0.94;
            transform: translateY(2px);
            transition: opacity 0.25s ease, transform 0.25s ease;
        }

        .aitf-ai-log-time {
            color: #64748b;
            flex: 0 0 58px;
        }

        .aitf-ai-log-level {
            border-radius: 4px;
            flex: 0 0 54px;
            font-size: 10px;
            font-weight: 800;
            letter-spacing: 0.04em;
            padding: 1px 5px;
            text-align: center;
        }

        .aitf-ai-log-line.info .aitf-ai-log-level {
            background: rgba(56, 189, 248, 0.10);
            color: #7dd3fc;
        }

        .aitf-ai-log-line.warn .aitf-ai-log-level {
            background: rgba(245, 158, 11, 0.12);
            color: #fbbf24;
        }

        .aitf-ai-log-line.success .aitf-ai-log-level {
            background: rgba(16, 185, 129, 0.12);
            color: #86efac;
        }

        .aitf-ai-log-line.audit .aitf-ai-log-level {
            background: rgba(168, 85, 247, 0.12);
            color: #d8b4fe;
        }

        .aitf-ai-log-text {
            color: #cbd5e1;
            flex: 1;
        }

        .aitf-ai-log-cursor {
            animation: aitf-cursor-blink 1s steps(1) infinite;
            color: #a5b4fc;
        }

        @keyframes aitf-cursor-blink {
            50% {
                opacity: 0;
            }
        }

        .aitf-ai-stats-panel {
            display: grid;
            gap: 10px;
            grid-template-columns: repeat(auto-fit, minmax(145px, 1fr));
            margin-top: 18px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-stat-card {
            background: rgba(15, 23, 42, 0.58);
            border: 1px solid rgba(148, 163, 184, 0.11);
            border-radius: 10px;
            min-height: 78px;
            padding: 12px;
            position: relative;
            transition: border-color 0.25s ease, transform 0.25s ease, box-shadow 0.25s ease;
        }

        .aitf-ai-stat-card:hover {
            border-color: rgba(165, 180, 252, 0.24);
            box-shadow: 0 10px 24px rgba(0, 0, 0, 0.18);
            transform: translateY(-1px);
        }

        .aitf-ai-stat-icon {
            align-items: center;
            background: rgba(99, 102, 241, 0.12);
            border: 1px solid rgba(165, 180, 252, 0.14);
            border-radius: 8px;
            color: #a5b4fc;
            display: inline-flex;
            height: 28px;
            justify-content: center;
            margin-bottom: 8px;
            width: 28px;
        }

        .aitf-ai-stat-label {
            color: #94a3b8;
            display: block;
            font-size: 11px;
            font-weight: 700;
            letter-spacing: 0.03em;
            line-height: 1.25;
            text-transform: uppercase;
        }

        .aitf-ai-stat-value {
            color: #f8fafc;
            display: block;
            font-size: 20px;
            font-weight: 800;
            line-height: 1.1;
            margin-top: 5px;
        }

        .aitf-ai-steps-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(205px, 1fr));
            gap: 10px;
            margin-top: 18px;
            border-top: 1px solid rgba(255, 255, 255, 0.06);
            padding-top: 14px;
            position: relative;
            z-index: 1;
        }

        .aitf-ai-step {
            align-items: center;
            background: rgba(15, 23, 42, 0.42);
            border: 1px solid rgba(148, 163, 184, 0.10);
            border-radius: 10px;
            color: #8794a8;
            display: flex;
            gap: 10px;
            min-height: 46px;
            padding: 9px 10px;
            font-size: 13px;
            font-weight: 650;
            transition: color 0.3s ease, background 0.3s ease, border-color 0.3s ease, box-shadow 0.3s ease, transform 0.3s ease;
        }

        .aitf-ai-step-icon {
            align-items: center;
            background: rgba(148, 163, 184, 0.07);
            border-radius: 8px;
            display: inline-flex;
            height: 28px;
            justify-content: center;
            width: 28px;
        }

        .aitf-ai-step-icon i {
            color: #475569;
            transition: color 0.3s ease, transform 0.3s ease;
        }

        .aitf-ai-step.active {
            background: rgba(99, 102, 241, 0.14);
            border-color: rgba(129, 140, 248, 0.52);
            box-shadow: 0 0 22px rgba(99, 102, 241, 0.22);
            color: #e0e7ff;
            transform: translateY(-1px);
        }

        .aitf-ai-step.active .aitf-ai-step-icon {
            background: rgba(99, 102, 241, 0.22);
            box-shadow: 0 0 18px rgba(99, 102, 241, 0.34);
        }

        .aitf-ai-step.active .aitf-ai-step-icon i {
            color: #bfdbfe;
            animation: aitf-step-pulse 1.3s ease-in-out infinite;
        }

        .aitf-ai-step.done {
            background: rgba(16, 185, 129, 0.08);
            border-color: rgba(52, 211, 153, 0.24);
            color: #34d399;
        }

        .aitf-ai-step.done .aitf-ai-step-icon {
            background: rgba(16, 185, 129, 0.13);
        }

        .aitf-ai-step.done .aitf-ai-step-icon i {
            color: #86efac;
        }

        @keyframes aitf-step-pulse {

            0%,
            100% {
                transform: scale(1);
                opacity: 0.8;
            }

            50% {
                transform: scale(1.14);
                opacity: 1;
            }
        }

        @media (max-width: 640px) {
            .aitf-ai-work-content {
                align-items: stretch;
                flex-direction: column;
                gap: 14px;
            }

            .aitf-ai-orb-container {
                align-self: center;
            }

            .aitf-ai-stats-panel,
            .aitf-ai-steps-grid {
                grid-template-columns: 1fr;
            }
        }

        .aitf-ai-status {
            border-radius: 8px;
            font-weight: 700;
            padding: 10px 14px;
            margin-bottom: 16px;
            font-size: 14px;
            border: 1px solid transparent;
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .aitf-ai-status.pass {
            background: rgba(16, 185, 129, 0.1);
            color: #34d399;
            border-color: rgba(16, 185, 129, 0.2);
        }

        .aitf-ai-status.review_required {
            background: rgba(245, 158, 11, 0.1);
            color: #fbbf24;
            border-color: rgba(245, 158, 11, 0.2);
        }

        .aitf-ai-status.manual_verification_required {
            background: rgba(99, 102, 241, 0.1);
            color: #818cf8;
            border-color: rgba(99, 102, 241, 0.2);
        }

        .aitf-ai-status.failed {
            background: rgba(239, 68, 68, 0.1);
            color: #f87171;
            border-color: rgba(239, 68, 68, 0.2);
        }

        /* Sleek Document Table wrap */
        .aitf-ai-doc-table-wrap {
            border: 1px solid rgba(255, 255, 255, 0.08);
            border-radius: 12px;
            background: rgba(15, 23, 42, 0.4);
            max-height: 380px;
            overflow-y: auto;
        }

        /* Custom Scrollbars */
        .aitf-ai-doc-table-wrap::-webkit-scrollbar {
            width: 6px;
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-track {
            background: rgba(0, 0, 0, 0.2);
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-thumb {
            background: rgba(99, 102, 241, 0.3);
            border-radius: 4px;
        }

        .aitf-ai-doc-table-wrap::-webkit-scrollbar-thumb:hover {
            background: rgba(99, 102, 241, 0.5);
        }

        .aitf-ai-doc-table {
            width: 100%;
            margin-bottom: 0;
            border-collapse: collapse;
        }

        .aitf-ai-doc-table th {
            background: rgba(15, 23, 42, 0.8) !important;
            border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
            color: #94a3b8 !important;
            font-size: 11px;
            font-weight: 600;
            text-transform: uppercase;
            padding: 12px 16px !important;
            position: sticky;
            top: 0;
            z-index: 10;
        }

        .aitf-ai-doc-table td {
            border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
            padding: 14px 16px !important;
            vertical-align: middle !important;
            color: #cbd5e1;
        }

        .aitf-ai-doc-table tbody tr {
            transition: background-color 0.2s;
        }

        .aitf-ai-doc-table tbody tr:hover {
            background-color: rgba(99, 102, 241, 0.04);
        }

        .aitf-ai-doc-name {
            color: #f1f5f9;
            font-weight: 600;
            font-size: 14px;
        }

        .aitf-ai-doc-link {
            color: #f1f5f9;
            display: inline-flex;
            align-items: center;
            text-decoration: none;
        }

        .aitf-ai-doc-link:hover,
        .aitf-ai-doc-link:focus {
            color: #ffffff;
            text-decoration: underline;
        }

        .aitf-ai-doc-meta {
            color: #94a3b8;
            font-size: 13px;
        }

        .doc-meta-separator {
            color: #475569;
            margin: 0 4px;
        }

        .aitf-ai-scan-pill {
            border-radius: 20px;
            display: inline-flex;
            align-items: center;
            gap: 5px;
            font-size: 11px;
            font-weight: 600;
            padding: 4px 10px;
            text-transform: uppercase;
        }

        .aitf-ai-scan-pill.scanned {
            background: rgba(16, 185, 129, 0.12);
            color: #34d399;
            border: 1px solid rgba(16, 185, 129, 0.3);
        }

        .aitf-ai-scan-pill.not-scanned {
            background: rgba(239, 68, 68, 0.12);
            color: #f87171;
            border: 1px solid rgba(239, 68, 68, 0.3);
        }

        .aitf-ai-doc-actions {
            display: flex;
            gap: 6px;
        }

        .aitf-ai-doc-actions .btn {
            border-radius: 6px;
            font-size: 11px;
            font-weight: 600;
            padding: 4px 8px;
            transition: all 0.2s;
        }

        .aitf-ai-doc-actions .btn-default {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(255, 255, 255, 0.1);
            color: #cbd5e1;
        }

        .aitf-ai-doc-actions .btn-default:hover {
            background: rgba(255, 255, 255, 0.15);
            color: #fff;
        }

        .aitf-ai-doc-actions .btn-primary {
            background: rgba(99, 102, 241, 0.2);
            border: 1px solid rgba(99, 102, 241, 0.4);
            color: #a5b4fc;
        }

        .aitf-ai-doc-actions .btn-primary:hover {
            background: rgba(99, 102, 241, 0.4);
            color: #fff;
        }

        .aitf-ai-empty {
            background: rgba(15, 23, 42, 0.2);
            border: 1px dashed rgba(99, 102, 241, 0.2);
            border-radius: 12px;
            color: #64748b;
            padding: 24px;
            text-align: center;
            font-size: 14px;
        }

        /* FIXED AI Response Section Styles */
        .aitf-ai-response-section {
