            .date-graph-cell.source-cell,
            .date-graph-cell.status-cell {
                grid-column: 2;
                padding-top: 0;
            }
        }

        @media print {
            body * {
                visibility: hidden !important;
            }

            #dateGraphPanel,
            #dateGraphPanel * {
                visibility: visible !important;
            }

            #dateGraphPanel {
                display: block !important;
                position: absolute;
                left: 0;
                top: 0;
                width: 100%;
                margin: 0;
                border: 0;
            }

            .date-graph-actions {
                display: none !important;
            }
        }
