                $statement->bindParam(':id', $service["service_id"]);
                $statement->execute();
                $saiService = $statement->fetch();
                $saiNextServiceType = aitfNextCertificationServiceType('SA-I');



                $saiActionDate = "SELECT MIN(action_id) as action_id, service_id, action, due_date, MAX(sent_date) as sent_date, MAX(is_deleted) as is_deleted FROM ca_service_dates WHERE service_id = :ssiService AND is_deleted = 'N' GROUP BY service_id, action, due_date ORDER BY due_date ASC";
                $statement = $db->prepare($saiActionDate);
                $statement->bindParam(':ssiService', $saiService['service']);
                $statement->execute();
                $allSaiDates = $statement->fetchAll();

                // Fetch SA-II dates stored against current SA-I service ONLY if SA-I CDC has been saved
                $nextSaiiServiceDates = array();

                // For old clients, if SA-II date rows already exist for this SA-I but crr_id is empty,
                // treat it as legacy CDC so that recalculation runs.
                if ((!isset($saiService['crr_id']) || empty($saiService['crr_id']))) {
                    $legacySaiiCheckQuery = "SELECT 1 FROM ca_service_dates WHERE service_id = :saiServiceId AND action IN ('Suspension Reminder', 'Suspend Letter', 'Withdrawal Reminder', 'Withdraw Letter') LIMIT 1";
                    $statement = $db->prepare($legacySaiiCheckQuery);
                    $statement->bindParam(':saiServiceId', $saiService['service']);
                    $statement->execute();
                    $legacySaiiRow = $statement->fetch();
                    if ($legacySaiiRow) {
                        $saiService['crr_id'] = 'LEGACY';
                    }
                }

                // Check if SA-I's CDC has been saved (crr_id exists in service_type_sai)
                if (isset($saiService['crr_id']) && !empty($saiService['crr_id'])) {
                    aitfSyncClientStatusDates($db, $saiService['service'], $_GET['customerid']);
                    $nextSaiiServiceDates = aitfFetchClientStatusDates($db, $saiService['service'], array('Suspension Reminder', 'Suspend Letter', 'Withdrawal Reminder', 'Withdraw Letter'));
                }
                $nextSaiiServiceDates = array_values(array_filter($nextSaiiServiceDates, function ($row) {
                    return !isset($row['is_deleted']) || $row['is_deleted'] != 'Y';
                }));

                $saiSuspendDate = '';
                $prevServiceQuery = "SELECT service_id FROM service WHERE customer_id = :id AND service_id < :currId ORDER BY service_id DESC LIMIT 1";
                $prevStmt = $db->prepare($prevServiceQuery);
                $prevStmt->bindParam(':id', $_GET['customerid']);
                $prevStmt->bindParam(':currId', $saiService['service']);
                $prevStmt->execute();
                $prevServiceRow = $prevStmt->fetch();
                if ($prevServiceRow) {
                    $prevServiceDates = aitfFetchClientStatusDates($db, $prevServiceRow['service_id'], array('Suspend Letter'));
                    foreach ($prevServiceDates as $action) {
                        if (trim($action['action']) == 'Suspend Letter' && !empty($action['due_date'])) {
                            $saiSuspendDate = $action['due_date'];
                            break;
