    <?php } ?>
    <script type="text/javascript">
        (function () {
            var aitfAiDocuments = [];
            var aitfAiStepTimer = null;
            var aitfAiLogInterval = null;
            var aitfAiStepIndex = 0;
            var aitfAiTypingTimers = [];
            var aitfAiOverviewMetrics = {};
            var aitfSelectedAiModel = 'fly-512b';
            var aitfLastAiDocumentKeys = [];
            var aitfLastAiPrompt = '';
            var aitfLastAiSummary = '';
            var aitfLastAiScanScope = '';
            var aitfAiModelLabels = {
                'fly-512b': 'Fly-512B',
                'swim-128b': 'Swim-128B'
            };

            function aitfEscapeHtml(value) {
                return String(value === null || value === undefined ? '' : value)
                    .replace(/&/g, '&amp;')
                    .replace(/</g, '&lt;')
                    .replace(/>/g, '&gt;')
                    .replace(/"/g, '&quot;')
                    .replace(/'/g, '&#039;');
            }

            function aitfSetAiStatus(text, type) {
                var iconHtml = '<i class="fa fa-info-circle"></i> ';
                if (type === 'pass') iconHtml = '<i class="fa fa-check-circle"></i> ';
                else if (type === 'failed') iconHtml = '<i class="fa fa-exclamation-triangle"></i> ';
                else if (type === 'review_required' || type === 'manual_verification_required') iconHtml = '<i class="fa fa-eye"></i> ';

                $('#aitfAiStatus')
                    .removeClass('pass review_required manual_verification_required failed')
                    .addClass(type || 'manual_verification_required')
                    .html(iconHtml + aitfEscapeHtml(text))
                    .show();
            }

            function aitfDefaultPrompt() {
                return 'Read the selected PDF documents carefully and behave like an AITF pre-audit reviewer. Find client name mismatch, address/GSTIN/contact mismatch, wrong or missing dates, scope mismatch, ISO standard mismatch, manday gaps, missing signatures, suspicious values, contradictions between documents, and any risk that can affect audit readiness. Give clear evidence, fair report accuracy from 0-100%, suggestion, and recommended action. Rate strictly from evidence: below 40 bad report, 50-60 fine, 60-70 good, 70-90 very good, 90+ perfect, and 95+ outstanding. Do not give good ratings unnecessarily and do not be biased.';
            }

            function aitfSetReplyBoxVisible(visible) {
                $('#aitfAiReplyBox').toggle(!!visible);
                if (!visible) {
                    $('#aitfAiReplyPrompt').val('');
                }
            }

            function aitfResponseDocumentKeys(response) {
                var keys = [];
                (response && response.documents ? response.documents : []).forEach(function (doc) {
                    if (doc.document_key && keys.indexOf(doc.document_key) === -1) {
                        keys.push(doc.document_key);
                    }
                });
                return keys;
            }

            function aitfBuildReplyPrompt(replyText) {
                var parts = [];
                if ($.trim(aitfLastAiPrompt)) {
                    parts.push('Previous prompt: ' + $.trim(aitfLastAiPrompt));
                }
                if ($.trim(aitfLastAiSummary)) {
                    parts.push('Previous GO ai summary: ' + $.trim(aitfLastAiSummary));
                }
                parts.push('User follow-up reply: ' + $.trim(replyText));
                parts.push('Answer this follow-up using the same selected documents, AITF rules, and the previous AI response context. Keep the answer focused on the user follow-up.');
                return parts.join("\n\n");
            }

            function aitfSoftwareFillPrompt() {
                return 'Scan all software-filled form data for this client. Read Contract Review, CA, SA-I, SA-II, RC, Release/Notification for Stage-I audit, Stage-II notification, audit schedules, agreements, certificate and review forms from the application database. Check whether forms are completely filled, required fields are missing, dates are wrong or inconsistent, client details mismatch, service stage values conflict, and whether any obvious mistake exists. Give clear evidence, affected form/table, current value, expected value if known, fair report accuracy from 0-100%, and recommended action. Rate strictly from evidence: below 40 bad report, 50-60 fine, 60-70 good, 70-90 very good, 90+ perfect, and 95+ outstanding. Do not give good ratings unnecessarily and do not be biased.';
            }

            function aitfFormatMetric(stat, value) {
                if (value === null || value === undefined || value === '') {
                    return '-';
                }
                var numeric = parseFloat(value);
                if (isNaN(numeric)) {
                    return aitfEscapeHtml(value);
                }
                if (stat === 'confidence_score') {
                    return Math.round(numeric) + '%';
                }
                if (stat === 'reasoning_time_ms') {
                    if (numeric >= 1000) {
                        return (numeric / 1000).toFixed(numeric >= 10000 ? 0 : 1) + 's';
                    }
                    return Math.round(numeric) + 'ms';
                }
                return Math.round(numeric).toLocaleString();
            }

            function aitfAnimateMetricValue($value, stat, nextValue) {
                if (!$value.length) {
                    return;
                }
                if (nextValue === null || nextValue === undefined || nextValue === '') {
                    $value.text('-').removeData('raw-value');
                    return;
                }
                var nextNumber = parseFloat(nextValue);
                if (isNaN(nextNumber)) {
                    $value.text(nextValue).removeData('raw-value');
                    return;
                }
                var currentNumber = parseFloat($value.data('raw-value'));
                if (isNaN(currentNumber)) {
                    currentNumber = 0;
                }
                $({ count: currentNumber }).animate({ count: nextNumber }, {
                    duration: 650,
                    easing: 'swing',
                    step: function (now) {
                        $value.text(aitfFormatMetric(stat, now));
                    },
                    complete: function () {
                        $value.data('raw-value', nextNumber).text(aitfFormatMetric(stat, nextNumber));
                    }
                });
            }

            function aitfRenderReasoningStats(metrics) {
                metrics = metrics || {};
                $('#aitfAiStatsPanel .aitf-ai-stat-value').each(function () {
                    var $value = $(this);
                    var stat = $value.data('stat');
                    if (Object.prototype.hasOwnProperty.call(metrics, stat)) {
                        aitfAnimateMetricValue($value, stat, metrics[stat]);
                    }
                });
            }

            function aitfResetReasoningStats() {
                $('#aitfAiStatsPanel .aitf-ai-stat-value').each(function () {
                    $(this).text('-').removeData('raw-value');
                });
            }

            function aitfCurrentLogTime() {
                var now = new Date();
                function pad(part) {
                    part = String(part);
                    return part.length < 2 ? '0' + part : part;
                }
                return [pad(now.getHours()), pad(now.getMinutes()), pad(now.getSeconds())].join(':');
            }

            function aitfAppendTypedLog(log) {
                var level = (log.level || 'INFO').toUpperCase();
                var type = (log.type || level.toLowerCase()).toLowerCase();
                var text = String(log.text || '');
                var $line = $('<div class="aitf-ai-log-line ' + aitfEscapeHtml(type) + '">' +
                    '<span class="aitf-ai-log-time">' + aitfCurrentLogTime() + '</span>' +
                    '<span class="aitf-ai-log-level">' + aitfEscapeHtml(level) + '</span>' +
                    '<span class="aitf-ai-log-text"></span><span class="aitf-ai-log-cursor">|</span>' +
                    '</div>');
                $line.data('full-text', text);
                var $text = $line.find('.aitf-ai-log-text');
                var $cursor = $line.find('.aitf-ai-log-cursor');
                $('#aitfAiWorkLog').append($line);
                var index = 0;
                var timer = window.setInterval(function () {
                    index += 1;
                    $text.text(text.slice(0, index));
                    var logContainer = document.getElementById('aitfAiWorkLog');
                    if (logContainer) {
                        logContainer.scrollTop = logContainer.scrollHeight;
                    }
                    if (index >= text.length) {
                        window.clearInterval(timer);
                        $cursor.remove();
                    }
                }, 14);
                aitfAiTypingTimers.push(timer);
            }

            function aitfRenderWorkSteps() {
                $('#aitfAiWorkSteps .aitf-ai-step').each(function () {
                    var $step = $(this);
                    var step = parseInt($(this).data('step'), 10);
                    var icon = $step.find('.aitf-ai-step-icon i');
                    var baseIcon = $step.data('icon') || 'fa-circle-o';
                    $step.removeClass('active done');
                    icon.removeClass().addClass('fa');
                    if (step < aitfAiStepIndex) {
                        $step.addClass('done');
                        icon.addClass('fa-check-circle');
                    } else if (step === aitfAiStepIndex) {
                        $step.addClass('active');
                        icon.addClass(baseIcon);
                    } else {
                        icon.addClass(baseIcon);
                    }
                });
            }

            function aitfStartWorkSteps(options) {
                options = options || {};
                aitfStopWorkSteps(false);
                aitfAiStepIndex = 0;
                $('#aitfAiWorkSteps').show();
                aitfResetReasoningStats();
                aitfRenderReasoningStats({
                    documents_scanned: options.documentCount,
                    rules_applied: aitfAiOverviewMetrics.rules_applied
                });
                aitfRenderWorkSteps();

                var reasoningLogs = [
                    { level: 'INFO', type: 'info', text: 'Reasoning session opened for ' + (options.modelLabel || 'GO ai') + '.' },
                    { level: 'INFO', type: 'info', text: 'Swimming through selected PDF streams and software-filled records.' },
                    { level: 'INFO', type: 'audit', text: 'Collecting evidence anchors: names, dates, scope, standards, GSTIN, mandays, signatures.' },
                    { level: 'INFO', type: 'audit', text: 'Understanding client context from active database rows and attached review history.' },
                    { level: 'WARN', type: 'warn', text: 'Ambiguous or missing evidence will be isolated for manual verification instead of guessed.' },
                    { level: 'INFO', type: 'audit', text: 'Assessing chronology, validity windows, service stage consistency, and rule coverage.' },
                    { level: 'INFO', type: 'info', text: 'Finding hidden contradictions across repeated client identity and certification fields.' },
                    { level: 'INFO', type: 'audit', text: 'Cross-checking document evidence against active AITF AI rules.' },
                    { level: 'INFO', type: 'info', text: 'Building insight clusters and confidence signals from returned evidence.' },
                    { level: 'SUCCESS', type: 'success', text: 'Preparing structured audit response with evidence, risk, confidence, and actions.' }
                ];

                $('#aitfAiWorkLog').empty();
                aitfAppendTypedLog({ level: 'INFO', type: 'info', text: 'Starting audit-readiness analyzer...' });
                var logIndex = 0;
                aitfAiLogInterval = window.setInterval(function () {
                    if (logIndex < reasoningLogs.length) {
                        aitfAppendTypedLog(reasoningLogs[logIndex++]);
                    }
                }, 1150);

                aitfAiStepTimer = window.setInterval(function () {
                    var totalSteps = $('#aitfAiWorkSteps .aitf-ai-step').length;
                    aitfAiStepIndex = Math.min(totalSteps - 1, aitfAiStepIndex + 1);
                    aitfRenderWorkSteps();
                }, 1650);
            }

            function aitfStopWorkSteps(markDone) {
                if (aitfAiStepTimer) {
                    window.clearInterval(aitfAiStepTimer);
                    aitfAiStepTimer = null;
                }
                if (aitfAiLogInterval) {
                    window.clearInterval(aitfAiLogInterval);
                    aitfAiLogInterval = null;
                }
                aitfAiTypingTimers.forEach(function (timer) {
                    window.clearInterval(timer);
                });
                aitfAiTypingTimers = [];
                $('#aitfAiWorkLog .aitf-ai-log-line').each(function () {
                    var fullText = $(this).data('full-text');
                    if (fullText) {
                        $(this).find('.aitf-ai-log-text').text(fullText);
                    }
                    $(this).find('.aitf-ai-log-cursor').remove();
                });
                if (markDone) {
                    aitfAiStepIndex = $('#aitfAiWorkSteps .aitf-ai-step').length;
                    aitfRenderWorkSteps();
                    aitfAppendTypedLog({ level: 'SUCCESS', type: 'success', text: 'Review compiled successfully. Final response is ready.' });
                    var logContainer = document.getElementById('aitfAiWorkLog');
                    if (logContainer) {
                        logContainer.scrollTop = logContainer.scrollHeight;
                    }
                } else {
                    $('#aitfAiWorkSteps').hide();
                }
            }

            function aitfSelectedDocumentKeys() {
                var keys = [];
                $('.aitf-ai-doc-check:checked').each(function () {
                    keys.push($(this).val());
                });
                return keys;
            }

            function aitfDocumentKeys(documents) {
                return (documents || []).map(function (doc) {
                    return doc.document_key;
                }).filter(function (key) {
                    return !!key;
                });
            }

            function aitfSetAnalyzeButtons(disabled) {
                var isDisabled = !!disabled;
                var hasDocuments = !!aitfAiDocuments.length;
                $('#aitfAnalyzeSelectedDocs, #aitfAnalyzeAllDocs, #aitfSelectAllDocs').prop('disabled', isDisabled || !hasDocuments);
                $('#aitfSendPromptBtn, #aitfScanSoftwareFill, #aitfAiReplyBtn').prop('disabled', isDisabled);
            }

            function aitfSetSelectedAiModel(modelId) {
                if (modelId !== 'fly-512b' && modelId !== 'swim-128b') {
                    modelId = 'fly-512b';
                }
                aitfSelectedAiModel = modelId;
                $('.aitf-ai-model-option').each(function () {
                    var active = $(this).data('model') === modelId;
                    $(this).toggleClass('active', active).attr('aria-checked', active ? 'true' : 'false');
                });
            }

            function aitfRenderAiDocuments(documents) {
                aitfAiDocuments = documents || [];
                if (!aitfAiDocuments.length) {
                    $('#aitfAiDocuments').html('<div class="aitf-ai-empty">No uploaded PDF documents found for this client.</div>');
                    aitfSetAnalyzeButtons(false);
                    return;
                }
                var html = '<div class="aitf-ai-doc-table-wrap"><table class="table table-condensed aitf-ai-doc-table">';
                html += '<thead><tr>';
                html += '<th style="width:34px; text-align: center;"><input type="checkbox" id="aitfAiDocCheckAll"></th>';
                html += '<th>Document</th><th>Type / Cycle</th><th>AI Status</th><th>Last Analyzed</th><th>Actions</th>';
                html += '</tr></thead><tbody>';
                aitfAiDocuments.forEach(function (doc) {
                    var scanned = (doc.scan_status || 'Not Scanned') === 'Scanned';
                    var documentKey = doc.document_key || '';
                    var documentName = doc.document_name || doc.file_name || '';
                    var viewUrl = 'ai_document_review_api.php?action=view_document&document_key=' + encodeURIComponent(documentKey);
                    html += '<tr data-document-key="' + aitfEscapeHtml(doc.document_key || '') + '">';
                    html += '<td style="text-align: center;"><input type="checkbox" class="aitf-ai-doc-check" value="' + aitfEscapeHtml(doc.document_key || '') + '"></td>';
                    html += '<td><div class="aitf-ai-doc-name"><a class="aitf-ai-doc-link" href="' + aitfEscapeHtml(viewUrl) + '" target="_blank" rel="noopener" title="Open PDF in new tab"><i class="fa fa-file-pdf-o text-danger" style="margin-right: 6px;"></i>' + aitfEscapeHtml(documentName) + '</a></div></td>';
                    html += '<td><div class="aitf-ai-doc-meta">' + aitfEscapeHtml(doc.label || '') + ' <span class="doc-meta-separator">|</span> ' + aitfEscapeHtml(doc.service_type || '') + ' #' + aitfEscapeHtml(doc.service_id || '') + '</div></td>';
                    html += '<td><span class="aitf-ai-scan-pill ' + (scanned ? 'scanned' : 'not-scanned') + '">' + (scanned ? 'Scanned' : 'Not Scanned') + '</span></td>';
                    html += '<td>' + aitfEscapeHtml(doc.last_analyzed_at || '-') + '</td>';
                    html += '<td><div class="aitf-ai-doc-actions">';
                    if (scanned) {
                        html += '<button type="button" class="btn btn-xs btn-default aitf-view-ai-review" data-document-key="' + aitfEscapeHtml(doc.document_key || '') + '"><i class="fa fa-eye"></i> View AI Review</button>';
                    }
                    html += '<button type="button" class="btn btn-xs btn-primary aitf-reanalyze-ai-doc" data-document-key="' + aitfEscapeHtml(doc.document_key || '') + '"><i class="fa fa-refresh"></i> Re-Analyze</button>';
                    html += '</div></td></tr>';
                });
                html += '</tbody></table></div>';
                $('#aitfAiDocuments').html(html);
                aitfSetAnalyzeButtons(false);
            }

            function aitfConversationMessage(role, speaker, bodyHtml, extraId) {
                var idAttr = extraId ? ' id="' + aitfEscapeHtml(extraId) + '"' : '';
                return '<div' + idAttr + ' class="go-ai-chat-message ' + aitfEscapeHtml(role) + '">' +
                    '<span class="go-ai-chat-speaker">' + aitfEscapeHtml(speaker) + '</span>' +
                    bodyHtml +
                    '</div>';
            }

            function aitfEnsureConversation() {
                if (!$('#aitfAiResults .go-ai-conversation').length) {
                    $('#aitfAiResults').html('<div class="go-ai-conversation"></div>');
                }
                return $('#aitfAiResults .go-ai-conversation');
            }

            function aitfAppendUserReply(replyText) {
                var $conversation = aitfEnsureConversation();
                $conversation.append(aitfConversationMessage('user', 'You', '<p class="docora-response-para">' + aitfEscapeHtml(replyText) + '</p>'));
            }

            function aitfAppendAssistantLoading() {
                var $conversation = aitfEnsureConversation();
                $('#aitfAiReplyLoading').remove();
                $conversation.append(aitfConversationMessage('assistant', 'GO ai', '<div class="docora-loading-msg"><i class="fa fa-spinner fa-spin"></i> Reply in progress...</div>', 'aitfAiReplyLoading'));
            }

            function aitfNormalizeAccuracyScore(value) {
                var score = parseFloat(value);
                if (isNaN(score)) {
                    return null;
                }
                if (score <= 1) {
                    score = score * 100;
                }
                score = Math.max(0, Math.min(100, score));
                return Math.round(score);
            }

            function aitfAccuracyReview(score) {
                if (score === null || score === undefined) {
                    return '';
                }
                if (score >= 95) {
                    return 'Outstanding';
                }
                if (score >= 90) {
                    return 'Perfect';
                }
                if (score >= 70) {
                    return 'Very Good';
                }
                if (score >= 60) {
                    return 'Good';
                }
                if (score >= 50) {
                    return 'Fine';
                }
                if (score >= 40) {
                    return 'Needs Improvement';
                }
                return 'Bad Report';
            }

            function aitfBuildReportAccuracyHtml(rawAccuracy) {
                var score = aitfNormalizeAccuracyScore(rawAccuracy);
                if (score === null) {
                    return '';
                }
                var review = aitfAccuracyReview(score);
                var scale = 'Scale: below 40 Bad Report, 50-59 Fine, 60-69 Good, 70-89 Very Good, 90-94 Perfect, 95-100 Outstanding.';
                return '<p class="docora-response-para"><strong>Report Accuracy:</strong> ' + score + '% - <strong>' + aitfEscapeHtml(review) + '</strong><br>' +
                    '<span style="font-size: 13px; color: #64748b;">' + aitfEscapeHtml(scale) + ' Rating is evidence-based and should not be biased or unnecessarily positive.</span></p>';
            }

            function aitfBuildAiIssuesHtml(result) {
                if (!result) {
                    return '<p class="docora-empty-msg">No structured AI result was returned.</p>';
                }
                var issues = Array.isArray(result.findings) && result.findings.length ? result.findings : (Array.isArray(result.issues) ? result.issues : []);
                var manual = Array.isArray(result.manual_verifications) ? result.manual_verifications : [];

                var html = '';

                // 1. Summary paragraph
                if (result.summary) {
                    html += '<p class="docora-response-para">' + aitfEscapeHtml(result.summary) + '</p>';
                } else if (issues.length > 0 || manual.length > 0) {
                    html += '<p class="docora-response-para">I have reviewed the selected PDF documents as an AITF pre-audit reviewer. Below are the details and pre-audit issues found during the analysis.</p>';
                }

                if (!issues.length && !manual.length) {
                    html += '<p class="docora-empty-msg">No issues reported by GO ai.</p>';
                    return html;
                }

                // 2. Render each finding as a clean readable paragraph
                issues.forEach(function (issue) {
                    var severity = (issue.severity || 'info').toUpperCase();
                    var checkArea = issue.check_area || 'Review Issue';
                    var findingText = issue.finding || issue.reason || '';

                    var para = '<p class="docora-response-para">';
                    para += '<strong>' + aitfEscapeHtml(checkArea) + ' (' + severity + '):</strong> ';
                    para += aitfEscapeHtml(findingText);

                    if (issue.current_value || issue.expected_value) {
                        para += ' The document mentions "<strong>' + aitfEscapeHtml(issue.current_value || '-') + '</strong>", which does not match the expected context value of "<strong>' + aitfEscapeHtml(issue.expected_value || '-') + '</strong>".';
                    }

                    if (issue.evidence) {
                        para += ' <em>Evidence:</em> ' + aitfEscapeHtml(issue.evidence) + '.';
                    }

                    if (issue.suggestion) {
                        para += ' ' + aitfEscapeHtml(issue.suggestion);
                    }

                    if (issue.rule_reference) {
                        para += ' (Rule Ref: ' + aitfEscapeHtml(issue.rule_reference) + ')';
                    }

                    para += '</p>';
                    html += para;
                });

                // 3. Render manual verifications in paragraph format
                if (manual.length > 0) {
                    html += '<h4 style="font-size: 16px; font-weight: 700; color: #0f172a; margin-top: 24px; margin-bottom: 12px;">Manual Verifications Required</h4>';
                    manual.forEach(function (item) {
                        var checkArea = item.check_area || 'Manual Verification';
                        var reason = item.reason || 'Verification required';
                        var docs = Array.isArray(item.affected_documents) ? item.affected_documents.join(', ') : (item.affected_documents || '');

                        var para = '<p class="docora-response-para">';
                        para += '<strong>' + aitfEscapeHtml(checkArea) + ':</strong> ' + aitfEscapeHtml(reason);
                        if (docs) {
                            para += ' (Affected Documents: ' + aitfEscapeHtml(docs) + ')';
                        }
                        para += '</p>';
                        html += para;
                    });
                }

                // 4. Collect and display overall Recommended Actions
                var recActions = [];
                issues.forEach(function (issue) {
                    if (issue.recommended_action && recActions.indexOf(issue.recommended_action) === -1) {
                        recActions.push(issue.recommended_action);
                    }
                });
                if (recActions.length > 0) {
                    html += '<p class="docora-response-para" style="margin-top: 20px;"><strong>Recommended Action:</strong><br>' + aitfEscapeHtml(recActions.join(' ')) + '</p>';
                }

                // 5. Report Accuracy
                var avgConfidence = 0;
                var confCount = 0;
                issues.forEach(function (issue) {
                    if (issue.confidence !== undefined && issue.confidence !== null) {
                        var c = parseFloat(issue.confidence);
                        if (!isNaN(c)) {
                            avgConfidence += c;
                            confCount++;
                        }
                    }
                });
                var finalConfidence = (confCount > 0) ? (avgConfidence / confCount).toFixed(2) : null;
                if (result.confidence !== undefined && result.confidence !== null) {
                    finalConfidence = result.confidence;
                }
                if (finalConfidence !== null) {
                    html += aitfBuildReportAccuracyHtml(finalConfidence);
                }

                // 6. Disclaimer/Note
                html += '<p class="docora-response-para" style="font-size: 13px; color: #64748b; margin-top: 24px; border-top: 1px solid #f1f5f9; padding-top: 12px;"><strong>Note:</strong> Document evidence requires visual/manual verification for some sections.</p>';
                return html;
            }

            function aitfRenderAiIssues(result, appendToConversation) {
                var html = aitfBuildAiIssuesHtml(result);
                var messageHtml = aitfConversationMessage('assistant', 'GO ai', html);
                if (appendToConversation) {
                    var $conversation = aitfEnsureConversation();
                    $('#aitfAiReplyLoading').remove();
                    $conversation.append(messageHtml);
                } else {
                    $('#aitfAiResults').html('<div class="go-ai-conversation">' + messageHtml + '</div>');
                }
            }

            function aitfShowReviewResponse(response, appendToConversation) {
                if (!response || !response.success) {
                    aitfSetAiStatus(response && response.message ? response.message : 'Unable to load AI review.', 'failed');
                    return;
                }
                var result = response.result || {};
                var status = result.overall_status || response.status || 'manual_verification_required';
                var suffix = response.analyzed_at ? ' | analyzed ' + response.analyzed_at : '';
                aitfSetAiStatus('GO ai review #' + response.history_id + ' (' + status.replace(/_/g, ' ') + ')' + suffix, status);
                var responseKeys = aitfResponseDocumentKeys(response);
                if (responseKeys.length) {
                    aitfLastAiDocumentKeys = responseKeys;
                }
                if (response.scan_scope === 'software_fill') {
                    aitfLastAiScanScope = 'software_fill';
                }
                aitfLastAiSummary = result.summary || response.summary || '';

                // Populate review metadata header
                $('#docoraReviewId').text('#' + response.history_id);

                // Status Badge
                var statusText = status.replace(/_/g, ' ').toUpperCase();
                var statusClass = 'status-' + status;
                $('#docoraReviewStatusBadge')
                    .removeClass()
                    .addClass('docora-badge ' + statusClass)
                    .text(statusText);

                // Risk Badge
                var riskText = 'MEDIUM RISK';
                var riskClass = 'risk-medium';
                var issues = Array.isArray(result.findings) && result.findings.length ? result.findings : (Array.isArray(result.issues) ? result.issues : []);
                var hasCritical = issues.some(function (issue) {
                    return (issue.severity || '').toLowerCase() === 'critical';
                });

                if (status === 'pass') {
                    riskText = 'LOW RISK';
                    riskClass = 'risk-low';
                } else if (status === 'failed' || hasCritical) {
                    riskText = 'HIGH RISK';
                    riskClass = 'risk-high';
                }
                $('#docoraReviewRiskBadge')
                    .removeClass()
                    .addClass('docora-badge ' + riskClass)
                    .text(riskText);

                // Details
                $('#docoraReviewDate').text(response.analyzed_at || 'Just now');
                $('#docoraReviewModel').text(response.model || 'Fly-512B');

                var docCount = response.documents_count || response.document_count || (response.documents || []).length;
                $('#docoraReviewDocCount').text(docCount + ' document(s)');

                var rulesCount = response.rules_count || 0;
                $('#docoraReviewRulesCount').text(rulesCount + ' rule(s)');

                aitfRenderReasoningStats(response.reasoning_metrics || {});

                aitfRenderAiIssues(result, !!appendToConversation);
                aitfSetReplyBoxVisible(aitfLastAiDocumentKeys.length > 0 || aitfLastAiScanScope === 'software_fill' || $.trim(aitfLastAiPrompt) !== '');

                $('#aitfAiHistoryNote').text('Model: ' + (response.model || '') + '. Analyzed by: ' + (response.analyzed_by || ''));

                // Scroll smoothly to response section inside modal
                var $modal = $('#aitfAiReviewModal');
                var $container = $('#aitfAiResponseContainer');
                if ($modal.length && $container.length) {
                    var scrollTop = appendToConversation
                        ? $modal.scrollTop() + $container.position().top + $container.outerHeight()
                        : $modal.scrollTop() + $container.position().top - 20;
                    $modal.animate({ scrollTop: scrollTop }, 800);
                }
            }

            function aitfLoadAiOverview() {
                $('#aitfAiMetrics').text('Loading client documents and active rules...');
                $('#aitfAiHistoryNote').text('');
                aitfSetAnalyzeButtons(true);
                $.ajax({
                    url: 'ai_document_review_api.php',
                    type: 'GET',
                    dataType: 'json',
                    data: { action: 'overview' },
                    success: function (response) {
                        if (!response || !response.success) {
                            aitfSetAiStatus(response && response.message ? response.message : 'Unable to load GO ai overview.', 'failed');
                            return;
                        }
                        aitfRenderAiDocuments(response.documents || []);
                        aitfAiOverviewMetrics = response.reasoning_metrics || {};
                        $('#aitfAiMetrics').text((response.documents || []).length + ' PDF document(s) detected. ' + (response.active_rules_count || 0) + ' active AI rule(s).');
                        if (response.latest_history && response.latest_history.created_at) {
                            $('#aitfAiHistoryNote').text('Last review: ' + response.latest_history.created_at + ' (' + response.latest_history.status + ')');
                        }
                    },
                    error: function (xhr) {
                        aitfSetAiStatus(xhr.responseJSON && xhr.responseJSON.message ? xhr.responseJSON.message : 'Unable to load GO ai overview.', 'failed');
                    }
                });
            }

            function aitfAnalyzeDocuments(documentKeys, sourceButton, overridePrompt, preserveConversation, displayPrompt, scanScope) {
                var $btn = sourceButton ? $(sourceButton) : $();
                var selectedModel = aitfSelectedAiModel;
                var selectedModelLabel = aitfAiModelLabels[selectedModel] || 'GO ai';
                var promptText = overridePrompt !== undefined ? overridePrompt : $('#aitfAiUserPrompt').val();
                var normalizedScanScope = scanScope === 'software_fill' || !documentKeys.length ? 'software_fill' : '';
                if (!documentKeys.length && !$.trim(promptText) && normalizedScanScope !== 'software_fill') {
                    aitfSetAiStatus('Type a prompt or use Scan Software Fill.', 'failed');
                    $('#aitfAiUserPrompt').focus();
                    return;
                }
                aitfLastAiDocumentKeys = documentKeys.slice(0);
                aitfLastAiPrompt = displayPrompt !== undefined ? displayPrompt : promptText;
                aitfLastAiScanScope = normalizedScanScope;
                aitfSetAnalyzeButtons(true);
                $btn.data('original-html', $btn.html()).html('<i class="fa fa-spinner fa-spin"></i>');
                var targetLabel = normalizedScanScope === 'software_fill' && !documentKeys.length
                    ? 'client software-filled forms'
                    : documentKeys.length + ' selected PDF document(s)';
                aitfStartWorkSteps({
                    documentCount: documentKeys.length,
                    modelLabel: selectedModelLabel,
                    targetLabel: targetLabel
                });
                aitfSetAiStatus(selectedModelLabel + ' is analyzing ' + targetLabel + '.', 'manual_verification_required');

                if (preserveConversation) {
                    aitfAppendAssistantLoading();
                } else {
                    // Clear response section / show loading state
                    $('#docoraReviewId').text('-');
                    $('#docoraReviewStatusBadge').removeClass().addClass('docora-badge').text('-');
                    $('#docoraReviewRiskBadge').removeClass().addClass('docora-badge').text('-');
                    $('#docoraReviewDate').text('-');
                    $('#docoraReviewModel').text('-');
                    $('#docoraReviewDocCount').text('-');
                    $('#docoraReviewRulesCount').text('-');
                    $('#aitfAiResults').html('<div class="docora-loading-msg"><i class="fa fa-cogs fa-spin"></i> Deep reasoning in progress...</div>');
                    aitfSetReplyBoxVisible(false);
                }

                var analysisSucceeded = false;
                $.ajax({
                    url: 'ai_document_review_api.php',
                    type: 'POST',
                    dataType: 'json',
                    data: { action: 'analyze', document_keys: documentKeys.join(','), user_prompt: promptText, model: selectedModel, scan_scope: normalizedScanScope },
                    success: function (response) {
                        if (!response || !response.success) {
                            aitfSetAiStatus(response && response.message ? response.message : 'AI review failed.', 'failed');
                            if (preserveConversation) {
                                $('#aitfAiReplyLoading').remove();
                                aitfEnsureConversation().append(aitfConversationMessage('assistant', 'GO ai', '<p class="docora-empty-msg">No findings available.</p>'));
                            } else {
                                $('#aitfAiResults').html('<p class="docora-empty-msg">No findings available.</p>');
                            }
                            return;
                        }

                        response.status = response.result ? (response.result.overall_status || 'manual_verification_required') : 'manual_verification_required';
                        response.analyzed_at = new Date().toLocaleString();

                        analysisSucceeded = true;
                        aitfShowReviewResponse(response, !!preserveConversation);
                        aitfLoadAiOverview();
                    },
                    error: function (xhr) {
                        var message = xhr.responseJSON && xhr.responseJSON.message ? xhr.responseJSON.message : 'AI review failed. Check server logs for details.';
                        aitfSetAiStatus(message, 'failed');
                        if (preserveConversation) {
                            $('#aitfAiReplyLoading').remove();
                            aitfEnsureConversation().append(aitfConversationMessage('assistant', 'GO ai', '<p class="docora-empty-msg">' + aitfEscapeHtml(message) + '</p>'));
                        } else {
                            $('#aitfAiResults').html('<p class="docora-empty-msg">' + aitfEscapeHtml(message) + '</p>');
                        }
                    },
                    complete: function () {
                        aitfStopWorkSteps(analysisSucceeded);
                        if ($btn.length) {
                            $btn.html($btn.data('original-html') || $btn.html());
                        }
                        aitfSetAnalyzeButtons(false);
                    }
                });
            }

