            function showApplicationStatusDialog(options) {
                var opts = options || {};
                var $existing = $('#applicationStatusConfirmModal');
                if (!$existing.length) {
                    $('body').append(
                        '<div id="applicationStatusConfirmModal" class="app-status-modal" aria-hidden="true">' +
                        '<div class="app-status-modal__panel" role="dialog" aria-modal="true">' +
                        '<div class="app-status-modal__icon"><i class="fa fa-exchange"></i></div>' +
                        '<h3 class="app-status-modal__title"></h3>' +
                        '<p class="app-status-modal__message"></p>' +
                        '<div class="app-status-modal__actions">' +
                        '<button type="button" class="app-status-modal__btn app-status-modal__cancel">Cancel</button>' +
                        '<button type="button" class="app-status-modal__btn app-status-modal__confirm">Save Status</button>' +
                        '</div>' +
                        '</div>' +
                        '</div>'
                    );
                    $existing = $('#applicationStatusConfirmModal');
                }

                $existing.find('.app-status-modal__title').text(opts.title || 'Confirm Status Change');
                $existing.find('.app-status-modal__message').text(opts.message || '');
                $existing.find('.app-status-modal__confirm').text(opts.confirmText || 'Save Status').show().prop('disabled', false);
                $existing.find('.app-status-modal__cancel').text(opts.cancelText || 'Cancel').show();
                $existing.toggleClass('app-status-modal--info', !!opts.infoOnly);
                $existing.addClass('is-visible').attr('aria-hidden', 'false');

                if (opts.infoOnly) {
                    $existing.find('.app-status-modal__cancel').hide();
                    $existing.find('.app-status-modal__confirm').text(opts.confirmText || 'OK');
                }

                $existing.off('click.appStatus');
                $existing.on('click.appStatus', '.app-status-modal__cancel', function () {
                    $existing.removeClass('is-visible').attr('aria-hidden', 'true');
                    if (typeof opts.onCancel === 'function') {
                        opts.onCancel();
                    }
                });
                $existing.on('click.appStatus', '.app-status-modal__confirm', function () {
                    $existing.removeClass('is-visible').attr('aria-hidden', 'true');
                    if (typeof opts.onConfirm === 'function') {
                        opts.onConfirm();
                    }
                });
                $existing.on('click.appStatus', function (event) {
                    if (event.target === this && !opts.infoOnly) {
                        $existing.find('.app-status-modal__cancel').trigger('click');
                    }
                });
            }

            $(document).on('change', '.manual-application-status', function () {
                var $select = $(this);
                var newStatus = $select.val();
                var previousStatus = $select.attr('data-previous') || '';
                var customer = $select.attr('data-customer');

                if (!newStatus || newStatus === previousStatus) {
                    $select.val(previousStatus);
                    return;
                }

                showApplicationStatusDialog({
                    title: 'Change Application Status?',
                    message: 'This will update the client application status to "' + newStatus + '". The same status will appear on Home Page and IAF Dashboard after refresh.',
                    confirmText: 'Yes, Save Status',
                    cancelText: 'Keep Current',
                    onCancel: function () {
                        $select.val(previousStatus);
                    },
                    onConfirm: function () {
                        $select.prop('disabled', true);
                        $.ajax({
                            url: "addComments.php",
                            type: 'GET',
                            data: {
                                customerid: customer,
                                customerstatus: newStatus
                            },
                            success: function (data) {
                                if (typeof data === 'string' && data.trim().toLowerCase().indexOf('success') !== -1) {
                                    $('.manual-application-status').each(function () {
                                        var $statusSelect = $(this);
                                        var hasOption = $statusSelect.find('option').filter(function () {
                                            return $(this).val() === newStatus;
                                        }).length > 0;
                                        if (!hasOption) {
                                            $statusSelect.append($('<option>', { value: newStatus, text: newStatus }));
                                        }
                                        $statusSelect.val(newStatus).attr('data-previous', newStatus);
                                    });
                                    showApplicationStatusDialog({
                                        title: 'Status Saved',
                                        message: 'Application status has been updated successfully.',
                                        confirmText: 'OK',
                                        infoOnly: true
                                    });
                                } else {
                                    $select.val(previousStatus);
                                    showApplicationStatusDialog({
                                        title: 'Status Not Saved',
                                        message: 'Unable to save the application status. Please try again.',
                                        confirmText: 'OK',
                                        infoOnly: true
                                    });
                                }
                            },
                            error: function (data, status, err) {
                                $select.val(previousStatus);
                                showApplicationStatusDialog({
                                    title: 'Status Not Saved',
                                    message: 'Unable to save the application status. Error: ' + status,
                                    confirmText: 'OK',
                                    infoOnly: true
                                });
                            },
                            complete: function () {
                                $('.manual-application-status').prop('disabled', false);
                            }
                        });
                    }
                });
            });

            $(document).on('change', '.manual-cdc-status', function () {
                var $select = $(this);
                var newStatus = String($select.val() || '').trim();
                var previousStatus = String($select.attr('data-previous') || '').trim();
                var customerId = $select.attr('data-customer');
                var crrId = $select.attr('data-crr-id');
                var isoIndex = $select.attr('data-iso-index');
                var isoLabel = $select.attr('data-iso-label') || '';

                if (!newStatus || newStatus === previousStatus) {
                    $select.val(previousStatus);
                    return;
                }

                showApplicationStatusDialog({
                    title: 'Are you sure you want to change certification status?',
                    message: (isoLabel || ('ISO ' + (parseInt(isoIndex, 10) + 1))) + ' status will change from "' + (previousStatus || 'Not Set') + '" to "' + newStatus + '".',
                    confirmText: 'Yes, Change',
                    cancelText: 'Keep Current',
                    onCancel: function () {
                        $select.val(previousStatus);
                    },
                    onConfirm: function () {
                        $select.prop('disabled', true);

                        $.ajax({
                            url: 'updateCdcIsoDetails.php',
                            type: 'POST',
                            dataType: 'json',
                            data: {
                                crr_id: crrId,
                                customer_id: customerId,
                                iso_index: isoIndex,
                                iso_label: isoLabel,
                                field: 'certification_status',
                                value: newStatus
                            }
                        }).done(function (response) {
                            if (!response || !response.success) {
                                $select.val(previousStatus);
                                showApplicationStatusDialog({
                                    title: 'Status Not Saved',
                                    message: (response && response.message) || 'Unable to update ISO certification status.',
                                    confirmText: 'OK',
                                    infoOnly: true
                                });
                                return;
                            }

                            $('.manual-cdc-status').each(function () {
                                var $statusSelect = $(this);
                                if (
                                    String($statusSelect.attr('data-crr-id')) === String(crrId) &&
                                    String($statusSelect.attr('data-iso-index')) === String(isoIndex)
                                ) {
                                    var hasOption = $statusSelect.find('option').filter(function () {
                                        return $(this).val() === response.value;
                                    }).length > 0;
                                    if (!hasOption) {
                                        $statusSelect.append($('<option>', { value: response.value, text: response.value }));
                                    }
                                    $statusSelect.val(response.value).attr('data-previous', response.value);
                                }
                            });

                            showApplicationStatusDialog({
                                title: 'Status Saved',
                                message: (isoLabel || ('ISO ' + (parseInt(isoIndex, 10) + 1))) + ' certification status has been updated to "' + response.value + '".',
                                confirmText: 'OK',
                                infoOnly: true
                            });
                        }).fail(function (xhr) {
                            var response = xhr.responseJSON || {};
                            $select.val(previousStatus);
                            showApplicationStatusDialog({
                                title: 'Status Not Saved',
                                message: response.message || 'Unable to update ISO certification status.',
                                confirmText: 'OK',
                                infoOnly: true
                            });
                        }).always(function () {
                            $select.prop('disabled', false);
                        });
                    }
                });
            });

            $(document).on('change', '.manual-cdc-accreditation', function () {
                var $select = $(this);
                var newAccreditation = String($select.val() || '').trim().toUpperCase();
                var previousAccreditation = String($select.attr('data-previous') || '').trim().toUpperCase();
                var customerId = $select.attr('data-customer');
                var crrId = $select.attr('data-crr-id');
                var isoIndex = $select.attr('data-iso-index');
                var isoLabel = $select.attr('data-iso-label') || '';

                if (
                    (newAccreditation !== 'NABCB' && newAccreditation !== 'SELF') ||
                    newAccreditation === previousAccreditation
                ) {
                    $select.val(previousAccreditation);
                    return;
                }

                showApplicationStatusDialog({
                    title: 'Are you sure you want to change accreditation?',
                    message: 'Accreditation will change from "' + (previousAccreditation || 'Not Set') + '" to "' + newAccreditation + '".',
                    confirmText: 'Yes, Change',
                    cancelText: 'Keep Current',
                    onCancel: function () {
                        $select.val(previousAccreditation);
                    },
                    onConfirm: function () {
                        $select.prop('disabled', true);

                        $.ajax({
                            url: 'updateCdcIsoDetails.php',
                            type: 'POST',
                            dataType: 'json',
                            data: {
                                crr_id: crrId,
                                customer_id: customerId,
                                iso_index: isoIndex,
                                iso_label: isoLabel,
                                field: 'accreditation',
                                value: newAccreditation
                            }
                        }).done(function (response) {
                            if (!response || !response.success) {
                                $select.val(previousAccreditation);
                                showApplicationStatusDialog({
                                    title: 'Accreditation Not Saved',
                                    message: (response && response.message) || 'Unable to update accreditation. Please try again.',
                                    confirmText: 'OK',
                                    infoOnly: true
                                });
                                return;
                            }

                            $('.manual-cdc-accreditation').each(function () {
                                var $accreditationSelect = $(this);
                                if (
                                    String($accreditationSelect.attr('data-crr-id')) === String(crrId) &&
                                    String($accreditationSelect.attr('data-iso-index')) === String(isoIndex)
                                ) {
                                    $accreditationSelect
                                        .val(response.value)
                                        .attr('data-previous', response.value);
                                }
                            });

                            if (String($('#cdcModel .crr_Id').val()) === String(crrId)) {
                                $('#cdcIsoAccreditationList .cdc-iso-accreditation').each(function () {
                                    var $cdcSelect = $(this);
                                    if (String($cdcSelect.attr('data-iso-index')) === String(isoIndex)) {
                                        $cdcSelect
                                            .val(response.value)
                                            .data('previous-accreditation', response.value);
                                    }
                                });
                                if (String(isoIndex) === '0') {
                                    $('#cdcModel .accreditation')
                                        .val(response.value)
                                        .data('previous-accreditation', response.value);
                                }
                                if (typeof collectCdcIsoMetadata === 'function') {
                                    collectCdcIsoMetadata();
                                }
                            }

                            showApplicationStatusDialog({
                                title: 'Accreditation Saved',
                                message: (isoLabel || ('ISO ' + (parseInt(isoIndex, 10) + 1))) + ' accreditation has been updated to "' + response.value + '".',
                                confirmText: 'OK',
                                infoOnly: true
                            });
                        }).fail(function (xhr) {
                            var response = xhr.responseJSON || {};
                            $select.val(previousAccreditation);
                            showApplicationStatusDialog({
                                title: 'Accreditation Not Saved',
                                message: response.message || 'Unable to update accreditation. Please try again.',
                                confirmText: 'OK',
                                infoOnly: true
                            });
                        }).always(function () {
                            $select.prop('disabled', false);
                        });
                    }
                });
            });

            var pendingLetterDelete = null;

            function closeLetterDeleteModal() {
                $('#letterActionDeleteModal').removeClass('is-visible').attr('aria-hidden', 'true');
                pendingLetterDelete = null;
            }

            function deletePendingLetterRow() {
                if (!pendingLetterDelete || pendingLetterDelete.$link.data('deleting')) {
                    return false;
                }

                var item = pendingLetterDelete;
                item.$link.data('deleting', true).css('pointer-events', 'none');
                $('#letterActionDeleteModal .letter-delete-confirm').prop('disabled', true).html('<i class="fa fa-spinner fa-spin"></i> Deleting');

                $.ajax({
                    url: 'addComments.php',
                    type: 'POST',
                    dataType: 'json',
                    data: {
                        rowidac: item.rowid,
                        customer: item.customer,
                        ajax: 1
                    },
                    success: function (response) {
                        if (response && response.status === 'success') {
                            item.$row.fadeOut(200, function () {
                                $(this).remove();
                            });
                            closeLetterDeleteModal();
                            return;
                        }

                        alert(response && response.message ? response.message : 'Unable to delete this row.');
                        item.$link.data('deleting', false).css('pointer-events', '');
                    },
                    error: function () {
                        alert('Unable to delete this row.');
                        item.$link.data('deleting', false).css('pointer-events', '');
                    },
                    complete: function () {
                        $('#letterActionDeleteModal .letter-delete-confirm').prop('disabled', false).html('<i class="fa fa-trash"></i> Delete');
                    }
                });
            }

            $('body').on('click', '.deleteLetterAccount', function (e) {
                e.preventDefault();

                var $link = $(this);
                if ($link.is('[disabled]') || $link.data('deleting')) {
                    return false;
                }

                var rowid = $link.attr('data-action');
                var customer = $link.attr('data-customer');

                if (!rowid || !customer) {
                    alert('Unable to delete this row.');
                    return false;
                }

                pendingLetterDelete = {
                    $link: $link,
                    $row: $link.closest('tr'),
                    rowid: rowid,
                    customer: customer
                };

                $('#letterActionDeleteModal').addClass('is-visible').attr('aria-hidden', 'false');
            });

            $('body').on('click', '.letter-delete-confirm', function () {
                deletePendingLetterRow();
            });

            $('body').on('click', '.letter-delete-cancel, .letter-delete-close', function () {
                closeLetterDeleteModal();
            });

            $('body').on('click', '#letterActionDeleteModal', function (e) {
                if (e.target === this) {
                    closeLetterDeleteModal();
                }
            });

