                                    }
                                },
                                error: function () {
                                    console.log('Edit CDC RC - Could not fetch merged ISO list');
                                }
                            });
                        }

                        $('#cdcModel').modal('show');
                    },
                    error: function (data, status, err) {
                        alert(status);
                    }
